__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEVEL_DATA",{enumerable:!0,get:function(){return u}});var t=r(d[0]),n=r(d[1]),_=r(d[2]),o=r(d[3]);const u={words:(0,r(d[4]).withExamples)(o.N4_WORDS,_.N4_EXAMPLES),grammar:t.N4_GRAMMAR,reading:n.N4_READING}},1911,[1921,1922,1923,1924,1920]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N4_GRAMMAR",{enumerable:!0,get:function(){return n}});const n=[{id:'n4-g01',pattern:'〜たことがある',connection:'動詞た形 ＋ ことがある',meaning:'曾經〜過',example:{ja:'わたしは富士山に登ったことがあります。',zh:'我曾經爬過富士山。',highlight:'登ったことがあります'},tip:'接た形表示過去經驗；接辭書形「〜ことがある」則是「有時會〜」，常考兩者區別。',quiz:{blank:'ことがあります',distractors:['ことにします','ところです','ほうがいいです']}},{id:'n4-g02',pattern:'〜つもりだ',connection:'動詞辭書形／ない形 ＋ つもりだ',meaning:'打算〜',example:{ja:'来年、日本へ留学するつもりです。',zh:'我打算明年去日本留學。',highlight:'留学するつもりです'},tip:'「つもり」表事先已有的打算；「（よ）うと思う」偏當下的想法。否定可用「ないつもり」或「つもりはない」。',quiz:{blank:'つもりです',distractors:['ようです','そうです','ところです']}},{id:'n4-g03',pattern:'〜ようになる',connection:'動詞辭書形／可能形 ＋ ようになる',meaning:'變得能夠〜',example:{ja:'日本語が話せるようになりました。',zh:'變得會說日文了。',highlight:'話せるようになりました'},tip:'表能力或習慣的變化；否定的變化用「〜なくなる」，不說「ないようになる」。',quiz:{blank:'ようになりました',distractors:['ようにしました','ことになりました','そうになりました']}},{id:'n4-g04',pattern:'〜てしまう',connection:'動詞て形 ＋ しまう',meaning:'（不小心）〜了；做完',example:{ja:'電車に傘を忘れてしまいました。',zh:'把傘忘在電車上了。',highlight:'忘れてしまいました'},tip:'表遺憾或動作完成；口語縮約為「〜ちゃう／じゃう」（忘れちゃった），常考辨認。',quiz:{blank:'しまいました',distractors:['おきました','みました','あげました']}},{id:'n4-g05',pattern:'〜ておく',connection:'動詞て形 ＋ おく',meaning:'事先做好〜',example:{ja:'旅行の前に、ホテルを予約しておきます。',zh:'旅行前先把飯店訂好。',highlight:'予約しておきます'},tip:'表事先準備或維持現狀；口語縮約為「〜とく」（予約しとく）。注意與「〜てある」區別。',quiz:{blank:'おきます',distractors:['しまいます','みます','くれます']}},{id:'n4-g06',pattern:'〜そうだ（樣態）',connection:'動詞ます形／い形容詞去い／な形容詞語幹 ＋ そうだ',meaning:'看起來好像〜',example:{ja:'空が暗いですね。雨が降りそうです。',zh:'天色好暗，好像要下雨了。',highlight:'降りそうです'},tip:'樣態接ます形或去い；傳聞「そうだ」接普通形。いい→よさそう、ない→なさそう為常考例外。',quiz:{blank:'そうです',distractors:['ようです','らしいです','たいです']}},{id:'n4-g07',pattern:'〜たら',connection:'動詞た形 ＋ ら',meaning:'如果〜的話；〜之後',example:{ja:'駅に着いたら、電話してください。',zh:'到了車站請打電話給我。',highlight:'着いたら'},tip:'可表假設或確定的「〜之後」；後句可接請求、意志，這點和「〜と」不同。',quiz:{blank:'たら',distractors:['たり','ても','たのに']}},{id:'n4-g08',pattern:'〜ば',connection:'動詞ば形',meaning:'如果〜就〜',example:{ja:'急げば、間に合います。',zh:'快一點的話就來得及。',highlight:'急げば'},tip:'一般條件；後句是意志、請求時前句多為狀態性。い形容詞為〜ければ，名詞・な形為〜なら(ば)。',quiz:{blank:'急げば',distractors:['急いでも','急ぐのに','急がなければ']}},{id:'n4-g09',pattern:'〜のに',connection:'普通形 ＋ のに',meaning:'明明〜卻〜',example:{ja:'たくさん勉強したのに、試験に落ちた。',zh:'明明很用功讀書，考試卻沒過。',highlight:'勉強したのに'},tip:'表與預期相反的不滿或遺憾，後句不能接意志、請求；「ので」才是表原因。',quiz:{blank:'のに',distractors:['ので','から','ために']}},{id:'n4-g10',pattern:'〜やすい',connection:'動詞ます形 ＋ やすい',meaning:'容易〜',example:{ja:'このペンはとても書きやすいです。',zh:'這支筆非常好寫。',highlight:'書きやすい'},tip:'ます形＋やすい表容易；反義「〜にくい」。注意易混淆的「〜づらい」（帶主觀辛苦感）。',quiz:{blank:'やすい',distractors:['にくい','たい','そう']}},{id:'n4-g11',pattern:'〜ために',connection:'動詞辭書形／名詞の ＋ ために',meaning:'為了〜',example:{ja:'留学するために、お金をためています。',zh:'為了留學正在存錢。',highlight:'留学するために'},tip:'表目的時前後主語相同且接意志動詞；非意志動詞、可能形用「〜ように」。名詞＋のために也可表原因。',quiz:{blank:'ために',distractors:['のに','ので','ながら']}},{id:'n4-g12',pattern:'〜られる（被動）',connection:'動詞被動形',meaning:'被〜',example:{ja:'電車の中で足を踏まれました。',zh:'在電車裡被踩到腳了。',highlight:'踏まれました'},tip:'一段動詞＋られる、五段改あ段＋れる；動作者用「に」標示，是被動句基本考點。',quiz:{blank:'踏まれました',distractors:['踏みました','踏ませました','踏んでいました']}},{id:'n4-g13',pattern:'〜かもしれない',connection:'普通形（な形・名詞去だ） ＋ かもしれない',meaning:'說不定〜；也許〜',example:{ja:'午後から雪が降るかもしれません。',zh:'下午開始說不定會下雪。',highlight:'降るかもしれません'},tip:'表可能性約50%的推測；比「でしょう」不確定。な形・名詞直接接，不加だ。',quiz:{blank:'かもしれません',distractors:['そうです','ようにします','つもりです']}},{id:'n4-g14',pattern:'〜ほうがいい',connection:'動詞た形／ない形 ＋ ほうがいい',meaning:'最好〜（建議）',example:{ja:'熱があるなら、早く寝たほうがいいですよ。',zh:'如果發燒的話，最好早點睡喔。',highlight:'寝たほうがいい'},tip:'肯定多接た形，否定接ない形（〜ないほうがいい），不說「なかったほうがいい」。',quiz:{blank:'ほうがいい',distractors:['ばかり','つもり','そう']}},{id:'n4-g15',pattern:'〜すぎる',connection:'動詞ます形／形容詞語幹 ＋ すぎる',meaning:'太〜；過於〜',example:{ja:'昨日は飲みすぎて、頭が痛い。',zh:'昨天喝太多了，頭好痛。',highlight:'飲みすぎて'},tip:'接ます形或形容詞語幹；いい→よすぎる、ない→なさすぎる為常考例外。',quiz:{blank:'すぎて',distractors:['やすくて','にくくて','たくて']}},{id:'n4-g16',pattern:'〜にくい',connection:'動詞ます形 ＋ にくい',meaning:'很難〜；不容易〜',example:{ja:'この薬は苦くて飲みにくい。',zh:'這個藥很苦，很難吞。',highlight:'飲みにくい'},tip:'表做起來困難（多為物理、性質上）；反義「〜やすい」。',quiz:{blank:'にくい',distractors:['やすい','たい','たがる']}},{id:'n4-g17',pattern:'〜てみる',connection:'動詞て形 ＋ みる',meaning:'試著〜看看',example:{ja:'この新しいパンを食べてみてください。',zh:'請試吃看看這個新麵包。',highlight:'食べてみて'},tip:'表試著做看看；和「〜てみたい」「〜てみてください」搭配常考。',quiz:{blank:'みて',distractors:['おいて','しまって','あって']}},{id:'n4-g18',pattern:'〜てあげる',connection:'動詞て形 ＋ あげる',meaning:'為別人做〜',example:{ja:'妹に宿題を教えてあげました。',zh:'我教妹妹寫作業。',highlight:'教えてあげました'},tip:'我→別人；對長輩用「〜てさしあげる」，對晚輩・動物用「〜てやる」。當面對長輩使用會失禮。',quiz:{blank:'あげました',distractors:['もらいました','くれました','いただきました']}},{id:'n4-g19',pattern:'〜てもらう',connection:'動詞て形 ＋ もらう',meaning:'請別人為我做〜',example:{ja:'友達に駅まで送ってもらいました。',zh:'請朋友送我到車站。',highlight:'送ってもらいました'},tip:'主語是受惠者，施惠者用「に」；與「〜てくれる」主語相反，是授受考點。',quiz:{blank:'もらいました',distractors:['あげました','くれました','やりました']}},{id:'n4-g20',pattern:'〜てくれる',connection:'動詞て形 ＋ くれる',meaning:'別人為我做〜',example:{ja:'母が誕生日にケーキを作ってくれました。',zh:'媽媽在我生日時幫我做了蛋糕。',highlight:'作ってくれました'},tip:'別人為我（或我方）做；施惠者當主語用「が」，受惠者是我，不用「てもらう」的に。',quiz:{blank:'くれました',distractors:['もらいました','あげました','いただきました']}},{id:'n4-g21',pattern:'〜ようにする',connection:'動詞辭書形／ない形 ＋ ようにする',meaning:'盡量〜；設法做到〜',example:{ja:'毎日野菜を食べるようにしています。',zh:'我盡量每天吃蔬菜。',highlight:'食べるようにしています'},tip:'表為養成習慣而努力；「〜ようになる」是自然變化，「〜ことにする」是一次性決定。',quiz:{blank:'ようにしています',distractors:['ようになっています','そうにしています','ためにしています']}},{id:'n4-g22',pattern:'〜ように（目的）',connection:'動詞辭書形／ない形 ＋ ように',meaning:'為了能〜；以便〜',example:{ja:'後ろの人にも聞こえるように、大きい声で話してください。',zh:'請大聲說話，讓後面的人也聽得到。',highlight:'聞こえるように'},tip:'前接非意志動詞、可能形或ない形；意志動詞且主語相同時改用「ために」。',quiz:{blank:'ように',distractors:['ために','のに','ところに']}},{id:'n4-g23',pattern:'〜ことにする',connection:'動詞辭書形／ない形 ＋ ことにする',meaning:'決定〜（自己決定）',example:{ja:'来年、日本へ留学することにしました。',zh:'我決定明年去日本留學。',highlight:'留学することにしました'},tip:'表自己的決定；「ことにしている」表規定自己的習慣。與「ことになる」（非自己決定）常對比考。',quiz:{blank:'ことにしました',distractors:['ことになりました','ようにしました','つもりでした']}},{id:'n4-g24',pattern:'〜ことになる',connection:'動詞辭書形／ない形 ＋ ことになる',meaning:'（被）決定〜；變成〜',example:{ja:'来月から大阪で働くことになりました。',zh:'（公司決定）下個月起我要在大阪工作了。',highlight:'働くことになりました'},tip:'表外部或自然形成的決定；「ことになっている」表規定、慣例。與「ことにする」對比。',quiz:{blank:'ことになりました',distractors:['ことがありました','ところでした','そうでした']}},{id:'n4-g25',pattern:'〜と（條件）',connection:'動詞辭書形 ＋ と',meaning:'一〜就〜（必然結果）',example:{ja:'このボタンを押すと、ドアが開きます。',zh:'一按這個按鈕，門就會開。',highlight:'押すと'},tip:'表自然、必然結果或習慣；後句不能接意志、請求、命令，這點常考。',quiz:{blank:'と',distractors:['たら','ても','のに']}},{id:'n4-g26',pattern:'〜なら',connection:'普通形（な形・名詞去だ） ＋ なら',meaning:'如果是〜的話',example:{ja:'京都へ行くなら、秋がいいですよ。',zh:'如果要去京都，秋天比較好喔。',highlight:'行くなら'},tip:'承接對方話題給建議；前後時間可倒置（京都へ行くなら…，先決定才去），與「たら」不同。',quiz:{blank:'なら',distractors:['たら','と','ば']}},{id:'n4-g27',pattern:'〜ても',connection:'動詞て形／い形容詞くて／な形容詞・名詞で ＋ も',meaning:'即使〜也〜',example:{ja:'雨が降っても、試合は行います。',zh:'即使下雨，比賽也照常舉行。',highlight:'降っても'},tip:'表逆接假定；な形・名詞用「〜でも」。疑問詞＋ても＝「無論〜都」。',quiz:{blank:'ても',distractors:['たら','たり','ては']}},{id:'n4-g28',pattern:'〜させる（使役）',connection:'動詞ない形去ない ＋ せる／させる',meaning:'讓〜做；叫〜做',example:{ja:'先生は学生に作文を書かせました。',zh:'老師叫學生寫作文。',highlight:'書かせました'},tip:'五段改あ段＋せる、一段＋させる、する→させる。他動詞的對象用に，自動詞的對象用を。',quiz:{blank:'書かせました',distractors:['書かれました','書きました','書かせられました']}},{id:'n4-g29',pattern:'〜させられる（使役被動）',connection:'動詞ない形去ない ＋ せられる／させられる',meaning:'被迫〜',example:{ja:'子どものころ、母に野菜を食べさせられました。',zh:'小時候被媽媽逼著吃蔬菜。',highlight:'食べさせられました'},tip:'五段可縮約為「〜される」（書かされる），但す結尾不可（話させられる）。表被迫做不想做的事。',quiz:{blank:'食べさせられました',distractors:['食べさせました','食べられました','食べさせてもらいました']}},{id:'n4-g30',pattern:'〜らしい',connection:'普通形（な形・名詞去だ） ＋ らしい',meaning:'好像〜（根據聽聞推測）',example:{ja:'隣の部屋に新しい人が引っ越してきたらしい。',zh:'隔壁好像搬來了新的人。',highlight:'引っ越してきたらしい'},tip:'根據外部資訊的推測，語氣較客觀；名詞＋らしい也可表「典型的〜」（男らしい）。',quiz:{blank:'らしい',distractors:['ところ','ばかり','つもり']}},{id:'n4-g31',pattern:'〜ようだ',connection:'普通形（な形な・名詞の） ＋ ようだ',meaning:'好像〜；似乎〜',example:{ja:'誰も電話に出ない。留守のようだ。',zh:'都沒人接電話，好像不在家。',highlight:'留守のようだ'},tip:'根據自己觀察的推測；口語為「みたいだ」。名詞要加「の」（留守のようだ）。',quiz:{blank:'ようだ',distractors:['そうだ','らしい','ためだ']}},{id:'n4-g32',pattern:'〜そうだ（傳聞）',connection:'普通形 ＋ そうだ',meaning:'聽說〜',example:{ja:'天気予報によると、明日は晴れるそうです。',zh:'根據天氣預報，聽說明天會放晴。',highlight:'晴れるそうです'},tip:'傳聞接普通形（降るそうだ）；樣態接ます形（降りそうだ）。常考兩者接續區別。',quiz:{blank:'そうです',distractors:['つもりです','ところです','ことにします']}},{id:'n4-g33',pattern:'〜ないで（附帶）',connection:'動詞ない形 ＋ で',meaning:'不〜就〜；沒有〜而〜',example:{ja:'今朝は朝ご飯を食べないで学校へ来ました。',zh:'今天早上沒吃早餐就來學校了。',highlight:'食べないで'},tip:'表附帶狀況「不做〜就〜」；「〜なくて」表原因，不能用於此。書面語為「〜ずに」。',quiz:{blank:'ないで',distractors:['なくて','ながら','たら']}},{id:'n4-g34',pattern:'〜ずに',connection:'動詞ない形去ない ＋ ずに（する→せずに）',meaning:'不〜而〜',example:{ja:'辞書を使わずに、この本を読みました。',zh:'沒用字典就讀完了這本書。',highlight:'使わずに'},tip:'「〜ないで」的書面說法；する要變「せずに」，不說「しずに」，為常考點。',quiz:{blank:'ずに',distractors:['なくて','ないと','ないのに']}},{id:'n4-g35',pattern:'〜てある',connection:'他動詞て形 ＋ ある',meaning:'（有人特意）〜著',example:{ja:'壁に大きな地図が貼ってあります。',zh:'牆上貼著一張大地圖。',highlight:'貼ってあります'},tip:'他動詞＋てある表有人刻意做後留下的狀態；自動詞＋ている（貼ってある vs 開いている）常對比。',quiz:{blank:'あります',distractors:['います','おきます','しまいます']}},{id:'n4-g36',pattern:'〜ところだ',connection:'動詞辭書形／ている形／た形 ＋ ところだ',meaning:'正要〜；正在〜；剛剛〜',example:{ja:'今から出かけるところです。',zh:'我現在正要出門。',highlight:'出かけるところです'},tip:'辭書形＝正要、ている形＝正在、た形＝剛剛；「たばかり」強調心理上的剛剛，可隔較久。',quiz:{blank:'ところです',distractors:['ばかりです','ことがあります','ようです']}},{id:'n4-g37',pattern:'〜始める',connection:'動詞ます形 ＋ 始める',meaning:'開始〜',example:{ja:'赤ちゃんが急に泣き始めました。',zh:'嬰兒突然開始哭了。',highlight:'泣き始めました'},tip:'表動作開始；「〜出す」帶突然性，多用於非意志動作。複合動詞接ます形。',quiz:{blank:'始めました',distractors:['終わりました','続けました','すぎました']}},{id:'n4-g38',pattern:'〜（よ）うと思う',connection:'動詞意向形 ＋ と思う',meaning:'打算〜；想要〜',example:{ja:'夏休みに運転免許を取ろうと思っています。',zh:'我打算暑假考駕照。',highlight:'取ろうと思っています'},tip:'接意向形；「〜（よ）うとする」是「正要／試圖〜」，意思不同，常考混淆。',quiz:{blank:'と思っています',distractors:['としています','つもりです','ようにしています']}},{id:'n4-g39',pattern:'〜場合は',connection:'普通形／名詞の ＋ 場合は',meaning:'〜的情況下；如果〜',example:{ja:'火事の場合は、エレベーターを使わないでください。',zh:'發生火災時請不要搭電梯。',highlight:'火事の場合は'},tip:'表假設的情況，多用於規定、說明；名詞加「の」，後句多為指示或應對方法。',quiz:{blank:'場合は',distractors:['ように','までに','ほうが']}},{id:'n4-g40',pattern:'〜までに',connection:'名詞／動詞辭書形 ＋ までに',meaning:'在〜之前（期限）',example:{ja:'レポートは金曜日までに出してください。',zh:'報告請在星期五之前交。',highlight:'金曜日までに'},tip:'「までに」表期限（之前某時完成一次）；「まで」表持續到某時。是常考對比。',quiz:{blank:'までに',distractors:['から','だけ','ごろ']}},{id:'n4-g41',pattern:'〜に〜をあげる',connection:'人 ＋ に ＋ 物 ＋ を ＋ あげる',meaning:'給（別人）〜',example:{ja:'私は友達に誕生日のプレゼントをあげた。',zh:'我送了生日禮物給朋友。',highlight:'友達に誕生日のプレゼントをあげた'},tip:'我→別人（同輩）；對長輩用さしあげる，對晚輩、動植物用やる。',quiz:{blank:'あげた',distractors:['くれた','もらった','いただいた']}},{id:'n4-g42',pattern:'〜に〜をもらう',connection:'人 ＋ に／から ＋ 物 ＋ を ＋ もらう',meaning:'從〜那裡得到〜',example:{ja:'探偵は依頼人に古い写真をもらった。',zh:'偵探從委託人那裡拿到了一張舊照片。',highlight:'依頼人に古い写真をもらった'},tip:'主語是接受者，給予者用「に」或「から」；從公司、團體得到時只能用「から」。',quiz:{blank:'もらった',distractors:['あげた','くれた','やった']}},{id:'n4-g43',pattern:'〜が〜をくれる',connection:'人 ＋ が ＋（私に）＋ 物 ＋ を ＋ くれる',meaning:'（別人）給我〜',example:{ja:'姉が私に新しい傘をくれた。',zh:'姊姊給了我一把新傘。',highlight:'姉が私に新しい傘をくれた'},tip:'別人給我（我方），主語是給予者；不能用於我給別人。對長輩用くださる。',quiz:{blank:'くれた',distractors:['あげた','もらった','いただいた']}},{id:'n4-g44',pattern:'〜に〜をさしあげる',connection:'人 ＋ に ＋ 物 ＋ を ＋ さしあげる',meaning:'給（長輩）〜（謙讓）',example:{ja:'先生に手紙をさしあげました。',zh:'我寫了一封信給老師。',highlight:'先生に手紙をさしあげました'},tip:'あげる的謙讓語，用於給長輩；授受方向同あげる。',quiz:{blank:'さしあげました',distractors:['くださいました','いただきました','くれました']}},{id:'n4-g45',pattern:'〜に〜をいただく',connection:'人 ＋ に／から ＋ 物 ＋ を ＋ いただく',meaning:'從（長輩）那裡得到〜（謙讓）',example:{ja:'社長にお土産をいただきました。',zh:'我從社長那裡收到了伴手禮。',highlight:'社長にお土産をいただきました'},tip:'もらう的謙讓語，主語是我；施予者為長輩，用「に／から」。',quiz:{blank:'いただきました',distractors:['さしあげました','くださいました','くれました']}},{id:'n4-g46',pattern:'〜が〜をくださる',connection:'人 ＋ が ＋ 物 ＋ を ＋ くださる',meaning:'（長輩）給我〜（尊敬）',example:{ja:'部長が私に本をくださいました。',zh:'部長給了我一本書。',highlight:'部長が私に本をくださいました'},tip:'くれる的尊敬語，主語是長輩；ます形為「くださいます」（不是くださります）。',quiz:{blank:'くださいました',distractors:['いただきました','さしあげました','もらいました']}},{id:'n4-g47',pattern:'〜に〜をやる',connection:'人／動植物 ＋ に ＋ 物 ＋ を ＋ やる',meaning:'給（晚輩、動植物）〜',example:{ja:'毎朝、花に水をやっています。',zh:'我每天早上替花澆水。',highlight:'花に水をやって'},tip:'用於給晚輩、動植物；對人使用較粗魯，現代也常用「あげる」。',quiz:{blank:'やって',distractors:['くれて','もらって','くださって']}},{id:'n4-g48',pattern:'〜てさしあげる',connection:'動詞て形 ＋ さしあげる',meaning:'為（長輩）做〜（謙讓）',example:{ja:'お客様に駅までの道を教えてさしあげた。',zh:'我告訴客人到車站的路。',highlight:'教えてさしあげた'},tip:'為長輩做事的謙讓表達；當面直接說可能顯得施恩，常改用「お〜します」。',quiz:{blank:'さしあげた',distractors:['くださった','いただいた','くれた']}},{id:'n4-g49',pattern:'〜ていただく',connection:'動詞て形 ＋ いただく',meaning:'請（長輩）為我做〜（謙讓）',example:{ja:'先生に推薦状を書いていただきました。',zh:'請老師幫我寫了推薦信。',highlight:'書いていただきました'},tip:'もらう的謙讓語，主語為受惠者「我」，施惠長輩用「に」。',quiz:{blank:'いただきました',distractors:['さしあげました','くださいました','やりました']}},{id:'n4-g50',pattern:'〜てくださる',connection:'動詞て形 ＋ くださる',meaning:'（長輩）為我做〜（尊敬）',example:{ja:'刑事さんが事件の経緯を説明してくださった。',zh:'刑警先生為我們說明了案件的經過。',highlight:'説明してくださった'},tip:'くれる的尊敬語，長輩為我方做事；主語是長輩，用「が」。',quiz:{blank:'くださった',distractors:['いただいた','さしあげた','もらった']}},{id:'n4-g51',pattern:'〜てやる',connection:'動詞て形 ＋ やる',meaning:'為（晚輩、動物）做〜',example:{ja:'弟に宿題を手伝ってやった。',zh:'我幫弟弟做了功課。',highlight:'手伝ってやった'},tip:'為晚輩、動物做事；也可表「（報復地）給你好看」（〜てやる！）。',quiz:{blank:'やった',distractors:['くれた','もらった','くださった']}},{id:'n4-g52',pattern:'〜てくれませんか',connection:'動詞て形 ＋ くれませんか',meaning:'可以幫我〜嗎（請求）',example:{ja:'ちょっと窓を開けてくれませんか。',zh:'可以幫我開一下窗戶嗎？',highlight:'開けてくれませんか'},tip:'向平輩或晚輩的請求；更客氣依序為「てもらえませんか」「ていただけませんか」。',quiz:{blank:'くれませんか',distractors:['あげませんか','もらいませんか','おきませんか']}},{id:'n4-g53',pattern:'〜てもらえませんか',connection:'動詞て形 ＋ もらえませんか',meaning:'能不能請你〜（客氣請求）',example:{ja:'この荷物を預かってもらえませんか。',zh:'能不能請你幫我保管這件行李？',highlight:'預かってもらえませんか'},tip:'用可能形否定疑問，比「てくれませんか」更客氣；主語是說話者。',quiz:{blank:'もらえませんか',distractors:['あげませんか','くれましょうか','もらいましょうか']}},{id:'n4-g54',pattern:'〜ていただけませんか',connection:'動詞て形 ＋ いただけませんか',meaning:'能否請您〜（非常客氣的請求）',example:{ja:'昨夜のことを詳しく話していただけませんか。',zh:'能否請您詳細說說昨晚的事？',highlight:'話していただけませんか'},tip:'最常用的客氣請求；注意是「いただけませんか」（可能形），不是「いただきませんか」。',quiz:{blank:'いただけませんか',distractors:['さしあげませんか','くださいましょうか','いただきましょうか']}},{id:'n4-g55',pattern:'〜てくださいませんか',connection:'動詞て形 ＋ くださいませんか',meaning:'可否請您〜（尊敬的請求）',example:{ja:'もう一度確認してくださいませんか。',zh:'可否請您再確認一次？',highlight:'確認してくださいませんか'},tip:'くれる的尊敬語＋ませんか，用於向長輩請求；與「ていただけませんか」客氣程度相當。',quiz:{blank:'くださいませんか',distractors:['いただきませんか','さしあげませんか','くれましょうか']}},{id:'n4-g56',pattern:'〜てほしい',connection:'動詞て形 ＋ ほしい',meaning:'希望（別人）〜',example:{ja:'本当のことを話してほしい。',zh:'我希望你說出真相。',highlight:'話してほしい'},tip:'希望別人做某事，對象用「に」；自己想要東西用「名詞がほしい」，想做用「〜たい」。',quiz:{blank:'ほしい',distractors:['みたい','あげたい','おきたい']}},{id:'n4-g57',pattern:'〜ないでほしい',connection:'動詞ない形 ＋ でほしい',meaning:'希望（別人）不要〜',example:{ja:'この話は誰にも言わないでほしい。',zh:'希望你不要把這件事告訴任何人。',highlight:'言わないでほしい'},tip:'希望別人不要做；不說「なくてほしい」。',quiz:{blank:'ないでほしい',distractors:['なくてほしい','ないほしい','ずにほしい']}},{id:'n4-g58',pattern:'〜てもらいたい',connection:'動詞て形 ＋ もらいたい',meaning:'想請（別人）〜',example:{ja:'君にこの暗号を解いてもらいたい。',zh:'我想請你解開這個暗號。',highlight:'解いてもらいたい'},tip:'與「〜てほしい」意思相近；對方用「に」。對長輩用「〜ていただきたい」。',quiz:{blank:'もらいたい',distractors:['あげたい','くれたい','やりたい']}},{id:'n4-g59',pattern:'〜ていただきたい',connection:'動詞て形 ＋ いただきたい',meaning:'想請您〜（謙讓）',example:{ja:'皆さんにこの写真を見ていただきたいと思います。',zh:'希望各位看一下這張照片。',highlight:'見ていただきたい'},tip:'もらいたい的謙讓說法，多用於正式場合；常與「と思います」連用使語氣更委婉。',quiz:{blank:'いただきたい',distractors:['さしあげたい','くださりたい','くれたい']}},{id:'n4-g60',pattern:'〜させてください',connection:'動詞使役て形 ＋ ください',meaning:'請讓我〜',example:{ja:'その件は私に調べさせてください。',zh:'那件事請讓我來調查。',highlight:'調べさせてください'},tip:'請對方允許自己做某事；常考將使役形與ください組合，不是「〜てください」。',quiz:{blank:'させてください',distractors:['てあげてください','られてください','させられてください']}},{id:'n4-g61',pattern:'〜させてもらう',connection:'動詞使役て形 ＋ もらう',meaning:'請（對方）讓我〜',example:{ja:'少し考えさせてもらえませんか。',zh:'能讓我稍微考慮一下嗎？',highlight:'考えさせてもらえませんか'},tip:'請求允許讓我做；與「〜てもらえませんか」（請你做）主語方向不同，常考。',quiz:{blank:'させてもらえませんか',distractors:['てあげませんか','させてあげませんか','られてもらえませんか']}},{id:'n4-g62',pattern:'〜させていただく',connection:'動詞使役て形 ＋ いただく',meaning:'請允許我〜（謙讓）',example:{ja:'それでは、推理を発表させていただきます。',zh:'那麼，請容我發表推理。',highlight:'発表させていただきます'},tip:'以謙遜方式表示自己要做某事（請容我〜）；する動詞為「〜させていただく」。',quiz:{blank:'させていただきます',distractors:['していただきます','させてくださいます','されていただきます']}},{id:'n4-g63',pattern:'〜させてあげる',connection:'動詞使役て形 ＋ あげる',meaning:'讓（別人）〜（允許）',example:{ja:'子どもに好きなだけ遊ばせてあげた。',zh:'讓孩子盡情地玩了。',highlight:'遊ばせてあげた'},tip:'允許或讓別人做某事；對長輩不用，對方用「に」。',quiz:{blank:'せてあげた',distractors:['せてもらった','れてあげた','せられた']}},{id:'n4-g64',pattern:'〜させてくれる',connection:'動詞使役て形 ＋ くれる',meaning:'（別人）讓我〜',example:{ja:'父は私に一人で旅行させてくれた。',zh:'爸爸讓我一個人去旅行。',highlight:'旅行させてくれた'},tip:'別人允許我做某事，含感謝語氣；與「させられる」（被迫）意思相反。',quiz:{blank:'させてくれた',distractors:['させてあげた','させられた','してくれた']}},{id:'n4-g65',pattern:'〜てくれてありがとう',connection:'動詞て形 ＋ くれてありがとう',meaning:'謝謝你為我〜',example:{ja:'手伝ってくれてありがとう。',zh:'謝謝你幫我。',highlight:'手伝ってくれてありがとう'},tip:'對平輩的感謝；對長輩用「〜てくださって／ていただいてありがとうございます」。',quiz:{blank:'くれてありがとう',distractors:['あげてありがとう','もらってありがとう','やってありがとう']}},{id:'n4-g66',pattern:'〜ていただいてありがとうございます',connection:'動詞て形 ＋ いただいてありがとうございます',meaning:'感謝您為我〜（客氣）',example:{ja:'遠くから来ていただいてありがとうございます。',zh:'感謝您遠道而來。',highlight:'来ていただいてありがとうございます'},tip:'對長輩表達感謝；「〜てくださってありがとうございます」亦正確，兩者常並列。',quiz:{blank:'いただいて',distractors:['さしあげて','あげて','やって']}},{id:'n4-g67',pattern:'〜られる（可能）',connection:'一段動詞語幹／来る（こ）＋ られる',meaning:'能夠〜',example:{ja:'あの日は疲れていて、朝早く起きられなかった。',zh:'那天很累，早上沒辦法早起。',highlight:'起きられなかった'},tip:'一段動詞與来る的可能形；口語常說「起きれる」（ら抜き），考試以「られる」為正解。',quiz:{blank:'られなかった',distractors:['させなかった','たくなかった','すぎなかった']}},{id:'n4-g68',pattern:'〜える（可能動詞）',connection:'五段動詞語尾改え段 ＋ る',meaning:'能夠〜（五段動詞的可能形）',example:{ja:'彼は英語と中国語が話せる。',zh:'他會說英文和中文。',highlight:'話せる'},tip:'五段動詞改え段＋る；可能形的對象多用「が」（英語が話せる）。する→できる。',quiz:{blank:'話せる',distractors:['話す','話される','話させる']}},{id:'n4-g69',pattern:'〜られる（尊敬）',connection:'動詞被動形',meaning:'（對長輩的行為表示尊敬）',example:{ja:'社長は何時ごろ戻られますか。',zh:'社長大約幾點回來呢？',highlight:'戻られますか'},tip:'尊敬用法形同被動，但敬意比「お〜になる」低；需靠語境判斷不是被動。',quiz:{blank:'戻られますか',distractors:['お戻りしますか','戻らせますか','戻られさせますか']}},{id:'n4-g70',pattern:'〜られる（間接被動）',connection:'動詞被動形',meaning:'（受害、困擾的被動）',example:{ja:'帰り道で雨に降られてしまった。',zh:'回家路上被雨淋了。',highlight:'雨に降られて'},tip:'自動詞也能用被動表示受害（雨に降られる），中文無直接對應，是常考點。',quiz:{blank:'降られて',distractors:['降って','降らせて','降りて']}},{id:'n4-g71',pattern:'〜られる（物主被動）',connection:'名詞 ＋ を ＋ 動詞被動形',meaning:'（自己的東西）被〜',example:{ja:'電車の中で財布を盗まれた。',zh:'我在電車裡被偷了錢包。',highlight:'財布を盗まれた'},tip:'被動作的是自己的東西時，主語是人，物用「を」；不說「私の財布が盗まれた」表受害。',quiz:{blank:'盗まれた',distractors:['盗んだ','盗ませた','盗めた']}},{id:'n4-g72',pattern:'〜られる（無生物主語）',connection:'名詞 ＋ が ＋ 動詞被動形',meaning:'被〜（客觀敘述）',example:{ja:'この寺は三百年前に建てられた。',zh:'這座寺廟建於三百年前。',highlight:'建てられた'},tip:'無生物主語的被動多用於客觀敘述；創作、建造者用「によって」而非「に」。',quiz:{blank:'建てられた',distractors:['建てさせた','建てていた','建てた']}},{id:'n4-g73',pattern:'〜に（被動的行為者）',connection:'名詞 ＋ に ＋ 動詞被動形',meaning:'被〜（動作者）',example:{ja:'犯人は警察に捕まえられた。',zh:'犯人被警察抓到了。',highlight:'警察に捕まえられた'},tip:'被動句的動作者一般用「に」；創作、發明等用「によって」，來源可用「から」。',quiz:{blank:'に',distractors:['を','が','で']}},{id:'n4-g74',pattern:'〜させる（許可・放任）',connection:'動詞使役形',meaning:'讓〜（允許、放任）',example:{ja:'母は私に好きな仕事をさせてくれた。',zh:'媽媽讓我做喜歡的工作。',highlight:'好きな仕事をさせて'},tip:'使役也可表許可、放任；常與「〜てくれる」「〜てあげる」連用表示允許。',quiz:{blank:'させて',distractors:['させられて','されて','して']}},{id:'n4-g75',pattern:'〜を（使役對象）',connection:'名詞 ＋ を ＋ 自動詞使役形',meaning:'讓〜（自動詞的使役對象）',example:{ja:'冗談を言って、みんなを笑わせた。',zh:'我說了個笑話，逗大家笑。',highlight:'みんなを笑わせた'},tip:'自動詞使役的對象用「を」（みんなを笑わせる）；他動詞使役因已有を，對象改用に。',quiz:{blank:'を笑わせた',distractors:['に笑われた','を笑った','が笑わせた']}},{id:'n4-g76',pattern:'〜に（使役對象）',connection:'名詞 ＋ に ＋ 〜を ＋ 他動詞使役形',meaning:'讓〜做〜（他動詞的使役對象）',example:{ja:'部長は部下に報告書を書かせた。',zh:'部長叫部下寫報告書。',highlight:'部下に報告書を書かせた'},tip:'他動詞使役句中已有「を」，被使役者用「に」，避免一句兩個を。',quiz:{blank:'に',distractors:['を','が','で']}},{id:'n4-g77',pattern:'お〜になる',connection:'お ＋ 動詞ます形 ＋ になる',meaning:'（尊敬語）〜',example:{ja:'先生はもうお帰りになりました。',zh:'老師已經回去了。',highlight:'お帰りになりました'},tip:'接和語動詞ます形；「お〜になる」是尊敬語，「お〜する」是謙讓語，常考對比。',quiz:{blank:'になりました',distractors:['しました','いたしました','されました']}},{id:'n4-g78',pattern:'ご〜になる',connection:'ご ＋ 漢語動作名詞 ＋ になる',meaning:'（尊敬語）〜',example:{ja:'このパソコンをご利用になりますか。',zh:'您要使用這台電腦嗎？',highlight:'ご利用になりますか'},tip:'接漢語動作名詞；不說「ご〜される」（雙重敬語）。尊敬語用「ご〜になる」。',quiz:{blank:'になりますか',distractors:['しますか','いたしますか','させますか']}},{id:'n4-g79',pattern:'お〜ください',connection:'お ＋ 動詞ます形 ＋ ください',meaning:'請您〜（尊敬的請求）',example:{ja:'こちらで少々お待ちください。',zh:'請在這裡稍候。',highlight:'お待ちください'},tip:'「〜てください」的尊敬說法；和語動詞用お，漢語名詞用ご（ご記入ください）。',quiz:{blank:'ください',distractors:['します','いたします','になります']}},{id:'n4-g80',pattern:'ご〜ください',connection:'ご ＋ 漢語動作名詞 ＋ ください',meaning:'請您〜（尊敬的請求）',example:{ja:'お名前とご住所をご記入ください。',zh:'請填寫您的姓名和地址。',highlight:'ご記入ください'},tip:'接漢語動作名詞；和語動詞用「お〜ください」。例外：お電話ください等。',quiz:{blank:'ください',distractors:['します','いたします','になります']}},{id:'n4-g81',pattern:'お〜する',connection:'お ＋ 動詞ます形 ＋ する',meaning:'（謙讓語）我為您〜',example:{ja:'重そうですね。お持ちしましょうか。',zh:'看起來很重呢，我幫您拿吧？',highlight:'お持ちしましょうか'},tip:'謙讓語，為對方做某事；不可用於長輩自己的動作（✗先生がお持ちする）。',quiz:{blank:'しましょうか',distractors:['になりましょうか','くださいましょうか','されましょうか']}},{id:'n4-g82',pattern:'ご〜する',connection:'ご ＋ 漢語動作名詞 ＋ する',meaning:'（謙讓語）我為您〜',example:{ja:'会議室までご案内します。',zh:'我帶您到會議室。',highlight:'ご案内します'},tip:'漢語名詞的謙讓語；更謙恭為「ご〜いたします」。注意與尊敬「ご〜になる」區分。',quiz:{blank:'します',distractors:['になります','ください','されます']}},{id:'n4-g83',pattern:'お〜いたす',connection:'お ＋ 動詞ます形 ＋ いたす',meaning:'（更謙恭的謙讓語）〜',example:{ja:'ご注文の品をお届けいたします。',zh:'我將為您送上訂購的商品。',highlight:'お届けいたします'},tip:'比「お〜する」更謙恭；漢語名詞用「ご〜いたす」（ご案内いたします）。',quiz:{blank:'いたします',distractors:['になります','ください','なさいます']}},{id:'n4-g84',pattern:'お〜です',connection:'お ＋ 動詞ます形 ＋ です',meaning:'（尊敬語）您正在〜',example:{ja:'どなたをお探しですか。',zh:'您在找哪一位呢？',highlight:'お探しですか'},tip:'「お〜になっている」的簡潔尊敬說法，表對方當下的狀態或動作。',quiz:{blank:'ですか',distractors:['しますか','いたしますか','くださいますか']}},{id:'n4-g85',pattern:'〜でございます',connection:'名詞 ＋ でございます',meaning:'是〜（です的鄭重說法）',example:{ja:'こちらが事件現場でございます。',zh:'這裡就是案發現場。',highlight:'事件現場でございます'},tip:'「です」的鄭重說法；「でいらっしゃる」用於尊敬對方本人，「でございます」不用於對方。',quiz:{blank:'でございます',distractors:['でいらっしゃいます','でおります','でまいります']}},{id:'n4-g86',pattern:'〜でいらっしゃる',connection:'名詞 ＋ でいらっしゃる',meaning:'是〜（尊敬對方）',example:{ja:'失礼ですが、山田様でいらっしゃいますか。',zh:'不好意思，請問您是山田先生嗎？',highlight:'山田様でいらっしゃいますか'},tip:'對對方或第三方表尊敬的「です」；不可用於自己（✗私は山田でいらっしゃいます）。',quiz:{blank:'でいらっしゃいますか',distractors:['でございますか','でおりますか','でまいりますか']}},{id:'n4-g87',pattern:'〜ていらっしゃる',connection:'動詞て形 ＋ いらっしゃる',meaning:'正在〜（ている的尊敬語）',example:{ja:'先生は今、研究室で本を読んでいらっしゃいます。',zh:'老師現在正在研究室看書。',highlight:'読んでいらっしゃいます'},tip:'「〜ている」的尊敬語，主語是長輩；自己用「〜ております」。',quiz:{blank:'いらっしゃいます',distractors:['おります','まいります','ございます']}},{id:'n4-g88',pattern:'〜ております',connection:'動詞て形 ＋ おります',meaning:'正在〜（ている的謙讓語）',example:{ja:'皆様のお越しをお待ちしております。',zh:'我們恭候各位的光臨。',highlight:'お待ちしております'},tip:'「〜ている」的謙讓（丁重）語，主語是自己或己方；對長輩用「〜ていらっしゃる」。',quiz:{blank:'おります',distractors:['いらっしゃいます','あります','ございます']}},{id:'n4-g89',pattern:'〜てまいります',connection:'動詞て形 ＋ まいります',meaning:'〜去／〜來（謙讓語）',example:{ja:'資料を取ってまいります。',zh:'我去拿資料過來。',highlight:'取ってまいります'},tip:'「〜ていく／てくる」的謙讓語；尊敬語為「〜ていらっしゃる」。',quiz:{blank:'まいります',distractors:['いらっしゃいます','おいでになります','ございます']}},{id:'n4-g90',pattern:'〜てはいかがですか',connection:'動詞て形 ＋ はいかがですか',meaning:'〜如何呢（客氣的建議）',example:{ja:'一度、現場をご覧になってはいかがですか。',zh:'您要不要去現場看一次呢？',highlight:'ご覧になってはいかがですか'},tip:'客氣的建議；比「〜たらどうですか」禮貌。對長輩也常用。',quiz:{blank:'はいかがですか',distractors:['もいいですか','はいけません','からどうですか']}},{id:'n4-g91',pattern:'〜って（傳聞）',connection:'普通形 ＋ って',meaning:'聽說〜（口語）',example:{ja:'隣の家に泥棒が入ったって。',zh:'聽說隔壁家遭小偷了。',highlight:'泥棒が入ったって'},tip:'口語傳聞，等於「〜そうだ」；也可表引用「〜と言っていた」。',quiz:{blank:'って',distractors:['ばかり','ところ','ため']}},{id:'n4-g92',pattern:'〜と言っていた',connection:'普通形 ＋ と言っていた',meaning:'（某人）說過〜（轉述）',example:{ja:'彼はその夜ずっと家にいたと言っていた。',zh:'他說那晚一直都在家。',highlight:'家にいたと言っていた'},tip:'「と言っていた」轉述第三者說過的話；「と言った」只陳述當時說了，「と言われた」是被別人說。',quiz:{blank:'と言っていた',distractors:['を言っていた','と言われた','と言わせた']}},{id:'n4-g93',pattern:'〜ということだ（傳聞）',connection:'普通形 ＋ ということだ',meaning:'據說〜',example:{ja:'犯人は北へ逃げたということだ。',zh:'據說犯人往北邊逃了。',highlight:'逃げたということだ'},tip:'「ということだ」為較正式的傳聞，同「そうだ（傳聞）」；別與「ところだ（正要/剛）」混淆。',quiz:{blank:'ということだ',distractors:['ところだ','はずだ','ことにした']}},{id:'n4-g94',pattern:'〜だろう',connection:'普通形（な形・名詞去だ）＋ だろう',meaning:'大概〜吧（推測，常體）',example:{ja:'明日はたぶん雨だろう。',zh:'明天大概會下雨吧。',highlight:'雨だろう'},tip:'「だろう」是「でしょう」的常體；名詞、な形容詞直接接だろう，不加だ。',quiz:{blank:'だろう',distractors:['だった','つもりだ','ながら']}},{id:'n4-g95',pattern:'〜だろうと思う',connection:'普通形（な形・名詞去だ）＋ だろうと思う',meaning:'我想大概〜吧',example:{ja:'犯人はまだ近くにいるだろうと思う。',zh:'我想犯人大概還在附近吧。',highlight:'いるだろうと思う'},tip:'「だろうと思う」可說，「でしょうと思う」是錯誤用法；名詞・な形不加だ。',quiz:{blank:'だろうと思う',distractors:['でしょうと思う','ようと思う','そうと思う']}},{id:'n4-g96',pattern:'〜んじゃないか',connection:'普通形（な形・名詞＋な）＋ んじゃないか',meaning:'不是〜嗎；恐怕是〜吧',example:{ja:'あの男が嘘をついているんじゃないか。',zh:'該不會是那個男人在說謊吧？',highlight:'ついているんじゃないか'},tip:'「んじゃないか」表推測或懷疑，並非否定；名詞・な形要加な：犯人なんじゃないか。',quiz:{blank:'んじゃないか',distractors:['んじゃなくて','ないじゃないか','ばかりか']}},{id:'n4-g97',pattern:'〜かな',connection:'普通形 ＋ かな',meaning:'〜呢？（自言自語的疑問）',example:{ja:'あの鍵はどこに隠したのかな。',zh:'那把鑰匙到底藏在哪裡了呢？',highlight:'隠したのかな'},tip:'「かな」是自言自語的疑問，男女皆可用；問別人時用「か」或「の？」。',quiz:{blank:'かな',distractors:['ぞ','わ','とも']}},{id:'n4-g98',pattern:'〜かしら',connection:'普通形 ＋ かしら',meaning:'〜呢？（女性用語，自問）',example:{ja:'あの人、本当に犯人なのかしら。',zh:'那個人真的是犯人嗎？',highlight:'犯人なのかしら'},tip:'「かしら」與「かな」同義，但多為女性用語；名詞・な形可接「なのかしら」。',quiz:{blank:'かしら',distractors:['ぞ','とも','っけ']}},{id:'n4-g99',pattern:'〜そうな（樣態・連體）',connection:'動詞ます形／形容詞語幹 ＋ そうな ＋ 名詞',meaning:'看起來〜的（修飾名詞）',example:{ja:'彼は何か言いたそうな顔をしていた。',zh:'他一副好像有話想說的表情。',highlight:'言いたそうな顔'},tip:'樣態「そうだ」修飾名詞用「そうな」，修飾動詞用「そうに」；傳聞そうだ沒有そうな形。',quiz:{blank:'そうな',distractors:['そうに','そうの','そうだ']}},{id:'n4-g100',pattern:'〜そうに（樣態・連用）',connection:'動詞ます形／形容詞語幹 ＋ そうに ＋ 動詞',meaning:'看起來〜地',example:{ja:'子どもたちが楽しそうに遊んでいる。',zh:'孩子們看起來玩得很開心。',highlight:'楽しそうに遊んでいる'},tip:'「そうに＋動詞」表看起來〜地；「いい」要變「よさそう」，「ない」變「なさそう」。',quiz:{blank:'そうに',distractors:['そうな','そうの','そうだ']}},{id:'n4-g101',pattern:'〜なさそうだ',connection:'い形容詞去い＋く／な形容詞語幹・名詞＋では ＋ なさそうだ',meaning:'看起來不〜',example:{ja:'この事件は簡単ではなさそうだ。',zh:'這個案件看來並不簡單。',highlight:'簡単ではなさそうだ'},tip:'「ない」接樣態要變「なさそうだ」；動詞否定較常用「〜そうもない／そうにない」。',quiz:{blank:'なさそうだ',distractors:['なそうだ','なくそうだ','なさそうに']}},{id:'n4-g102',pattern:'〜そうもない',connection:'動詞ます形 ＋ そうもない',meaning:'看起來不太可能〜',example:{ja:'この雨はやみそうもない。',zh:'這場雨看起來停不了。',highlight:'やみそうもない'},tip:'「ます形＋そうもない」＝看樣子不會〜，同「そうにない」；別與傳聞「ないそうだ」混淆。',quiz:{blank:'そうもない',distractors:['ないそうだ','そうのない','らしくない']}},{id:'n4-g103',pattern:'〜ような（比喻）',connection:'名詞 ＋ の ／ 普通形 ＋ ような ＋ 名詞',meaning:'像〜一樣的',example:{ja:'夢を見ているような気分だ。',zh:'感覺就像在做夢一樣。',highlight:'夢を見ているような'},tip:'比喻「ような＋名詞」；口語可換「みたいな」。名詞要加の：夢のような。',quiz:{blank:'ような',distractors:['ように','みたい','そうな']}},{id:'n4-g104',pattern:'〜ように（比喻）',connection:'名詞 ＋ の ／ 普通形 ＋ ように',meaning:'像〜一樣地',example:{ja:'彼女は人形のように動かなかった。',zh:'她像洋娃娃一樣一動也不動。',highlight:'人形のように'},tip:'「ように＋動詞/形容詞」修飾用言，「ような＋名詞」修飾名詞，考題常考這兩者的選擇。',quiz:{blank:'のように',distractors:['のような','みたいな','のそうに']}},{id:'n4-g105',pattern:'〜のような（例示）',connection:'名詞 ＋ のような ＋ 名詞',meaning:'像〜這樣的（舉例）',example:{ja:'東京のような大きな町に住みたい。',zh:'我想住在像東京這樣的大城市。',highlight:'東京のような'},tip:'「AのようなB」舉A為B的例子；口語用「Aみたいな」。考題常與比喻用法並列。',quiz:{blank:'のような',distractors:['のように','みたい','のそうな']}},{id:'n4-g106',pattern:'〜らしい（典型）',connection:'名詞 ＋ らしい',meaning:'很有〜的樣子；像樣的',example:{ja:'今日は春らしい暖かい日だ。',zh:'今天是很有春天氣息的溫暖日子。',highlight:'春らしい'},tip:'名詞＋らしい表「典型、有〜的樣子」；推測的「らしい（好像）」接普通形，要靠語意區分。',quiz:{blank:'らしい',distractors:['そうな','みたい','ような']}},{id:'n4-g107',pattern:'〜がる',connection:'形容詞語幹 ＋ がる',meaning:'（第三人稱）覺得〜；顯得〜',example:{ja:'妹は暗い部屋を怖がる。',zh:'妹妹很怕暗的房間。',highlight:'怖がる'},tip:'「がる」用於第三人稱的感情；第一人稱用「怖い」。及物時對象用を：〜を怖がる。',quiz:{blank:'がる',distractors:['くなる','そうだ','らしい']}},{id:'n4-g108',pattern:'〜たがる',connection:'動詞ます形 ＋ たがる',meaning:'（第三人稱）想要〜',example:{ja:'子どもは何でも知りたがる。',zh:'小孩子什麼都想知道。',highlight:'知りたがる'},tip:'「〜たい」vs「〜たがる」：たがる用於第三人稱，常以「たがっている」表現在狀態。',quiz:{blank:'たがる',distractors:['たい','たがらない','そうだ']}},{id:'n4-g109',pattern:'〜ほしがる',connection:'名詞 ＋ を ＋ ほしがる',meaning:'（第三人稱）想要〜',example:{ja:'弟は新しいゲームをほしがっている。',zh:'弟弟想要新的遊戲。',highlight:'ほしがっている'},tip:'第一人稱「〜がほしい」，第三人稱「〜をほしがる」；注意助詞由が變を。',quiz:{blank:'ほしがっている',distractors:['ほしい','ほしかった','ほしくなる']}},{id:'n4-g110',pattern:'〜てくる（變化）',connection:'動詞て形 ＋ くる',meaning:'漸漸〜起來（變化到現在）',example:{ja:'だんだん寒くなってきた。',zh:'天氣漸漸變冷了。',highlight:'寒くなってきた'},tip:'變化「てくる」表從過去到現在；「ていく」表從現在往未來。常與だんだん搭配。',quiz:{blank:'てきた',distractors:['てあった','ておいた','てみた']}},{id:'n4-g111',pattern:'〜ていく（變化）',connection:'動詞て形 ＋ いく',meaning:'〜下去（變化持續到未來）',example:{ja:'これからも日本語を勉強していくつもりだ。',zh:'今後我也打算繼續學日文。',highlight:'勉強していく'},tip:'「ていく」表變化或動作從現在持續到未來，常與「これから」搭配；過去到現在用「てくる」。',quiz:{blank:'ていく',distractors:['てある','てくる','てあげる']}},{id:'n4-g112',pattern:'〜てくる（去做再回來）',connection:'動詞て形 ＋ くる',meaning:'去〜（再回來）',example:{ja:'ちょっと現場を見てくる。',zh:'我去現場看一下就回來。',highlight:'見てくる'},tip:'「てくる」可表「去做〜再回來」，如「買ってくる」；與表變化的「てくる」靠語境區分。',quiz:{blank:'てくる',distractors:['てある','ていった','てきた']}},{id:'n4-g113',pattern:'〜ていく（移動方向）',connection:'動詞て形 ＋ いく',meaning:'〜著去；〜離去',example:{ja:'怪しい男が走っていった。',zh:'一個可疑的男人跑走了。',highlight:'走っていった'},tip:'移動方向：「ていく」表離說話者而去，「てくる」表朝說話者而來。',quiz:{blank:'ていった',distractors:['てあった','ておいた','てみた']}},{id:'n4-g114',pattern:'〜てくる（出現）',connection:'動詞て形 ＋ くる',meaning:'〜出來（開始出現）',example:{ja:'ドアの向こうから声が聞こえてきた。',zh:'從門的另一邊傳來了聲音。',highlight:'聞こえてきた'},tip:'「てくる」可表事物出現、被感知，常接「聞こえる・見える・出る」等動詞。',quiz:{blank:'てきた',distractors:['ていった','てあった','ておいた']}},{id:'n4-g115',pattern:'〜続ける',connection:'動詞ます形 ＋ 続ける',meaning:'一直〜；持續〜',example:{ja:'彼は三時間も黙り続けた。',zh:'他足足沉默了三個小時。',highlight:'黙り続けた'},tip:'「ます形＋続ける」＝持續〜；「始める」開始、「終わる」結束、「出す」突然開始。',quiz:{blank:'続けた',distractors:['始めた','終わった','出した']}},{id:'n4-g116',pattern:'〜終わる',connection:'動詞ます形 ＋ 終わる',meaning:'〜完',example:{ja:'この本はもう読み終わった。',zh:'這本書我已經看完了。',highlight:'読み終わった'},tip:'「ます形＋終わる」＝做完；意志性動作也可用「終える」。注意與「〜てしまう」的語感差異。',quiz:{blank:'終わった',distractors:['続けた','始めた','出した']}},{id:'n4-g117',pattern:'〜出す',connection:'動詞ます形 ＋ 出す',meaning:'突然開始〜',example:{ja:'赤ちゃんが急に泣き出した。',zh:'嬰兒突然哭了起來。',highlight:'泣き出した'},tip:'「出す」表突然開始，多用於非意志動作（泣く・降る）；「始める」較中性。',quiz:{blank:'出した',distractors:['終わった','続けた','直した']}},{id:'n4-g118',pattern:'〜直す',connection:'動詞ます形 ＋ 直す',meaning:'重新〜',example:{ja:'もう一度、証言を聞き直そう。',zh:'再重新聽一次證詞吧。',highlight:'聞き直そう'},tip:'「ます形＋直す」＝重新再做一次（改正），如「書き直す・やり直す」。',quiz:{blank:'直そう',distractors:['終わろう','出そう','続けよう']}},{id:'n4-g119',pattern:'〜方',connection:'動詞ます形 ＋ 方',meaning:'〜的方法',example:{ja:'この機械の使い方を教えてください。',zh:'請教我這台機器的用法。',highlight:'使い方'},tip:'「ます形＋方」＝〜的方法；「名詞を＋動詞」變「名詞の＋ます形方」：機械の使い方。',quiz:{blank:'方',distractors:['こと','もの','ため']}},{id:'n4-g120',pattern:'〜たばかりだ',connection:'動詞た形 ＋ ばかりだ',meaning:'剛〜不久',example:{ja:'日本に来たばかりで、まだ慣れていない。',zh:'我剛來日本不久，還不習慣。',highlight:'来たばかり'},tip:'「たばかり」強調說話者感覺剛不久（可隔一段時間）；「たところ」指動作剛結束的時點。',quiz:{blank:'ばかり',distractors:['まま','ほど','はず']}},{id:'n4-g121',pattern:'〜中（ちゅう）',connection:'名詞 ＋ 中（ちゅう）',meaning:'正在〜中',example:{ja:'社長は今、会議中です。',zh:'社長現在正在開會。',highlight:'会議中'},tip:'「中（ちゅう）」表正在進行，接動作名詞：会議中・電話中；別與「じゅう」混淆。',quiz:{blank:'中',distractors:['間','後','前']}},{id:'n4-g122',pattern:'〜中（じゅう）',connection:'名詞 ＋ 中（じゅう）',meaning:'整個〜；〜之內',example:{ja:'昨夜は一晩中、雨が降っていた。',zh:'昨晚下了一整夜的雨。',highlight:'一晩中'},tip:'「中（じゅう）」表整個期間或範圍：一日中・世界中；「ちゅう」表正在進行中。',quiz:{blank:'中',distractors:['間','ごろ','まで']}},{id:'n4-g123',pattern:'〜間',connection:'動詞辭書形／ている形 ＋ 間；名詞 ＋ の ＋ 間',meaning:'在〜期間（一直）',example:{ja:'夏休みの間、ずっと田舎にいた。',zh:'暑假期間我一直待在鄉下。',highlight:'夏休みの間'},tip:'「間」表整段期間持續，後接持續性狀態（ずっと〜）；「間に」表期間中的某一時點。',quiz:{blank:'間',distractors:['うちに','中に','前に']}},{id:'n4-g124',pattern:'〜間に',connection:'動詞辭書形／ている形 ＋ 間に；名詞 ＋ の ＋ 間に',meaning:'在〜期間（某時點）',example:{ja:'留守の間に、誰かが部屋に入った。',zh:'不在家的期間，有人進了房間。',highlight:'留守の間に'},tip:'「間に」後接一次性動作；與「うちに」相近，但「うちに」強調趁狀態改變之前。',quiz:{blank:'間に',distractors:['中で','うちで','ために']}},{id:'n4-g125',pattern:'〜ことがある（偶爾）',connection:'動詞辭書形／ない形 ＋ ことがある',meaning:'有時會〜',example:{ja:'彼は夜遅くまで帰らないことがある。',zh:'他有時會到很晚才回家。',highlight:'帰らないことがある'},tip:'「辭書形／ない形＋ことがある」＝有時會；「た形＋ことがある」＝曾經，考題常比較這兩者。',quiz:{blank:'ことがある',distractors:['ことにする','ことになる','ことができる']}},{id:'n4-g126',pattern:'〜ちゃう／〜じゃう',connection:'動詞て形去て ＋ ちゃう（で→じゃう）',meaning:'〜掉了（てしまう的口語）',example:{ja:'大事な証拠を捨てちゃった。',zh:'把重要的證據丟掉了。',highlight:'捨てちゃった'},tip:'「てしまう→ちゃう」「でしまう→じゃう」，過去式為ちゃった／じゃった。',quiz:{blank:'ちゃった',distractors:['じゃった','ちゃおう','ちゃだめ']}},{id:'n4-g127',pattern:'〜とく',connection:'動詞て形去て ＋ とく（で→どく）',meaning:'先〜好（ておく的口語）',example:{ja:'鍵は机の上に置いとくね。',zh:'鑰匙我先放在桌上喔。',highlight:'置いとく'},tip:'「ておく→とく」「でおく→どく」，如「読んどく」；屬口語縮約。',quiz:{blank:'とく',distractors:['どく','ちゃう','じゃう']}},{id:'n4-g128',pattern:'〜ばよかった',connection:'動詞ば形 ＋ よかった',meaning:'要是〜就好了（後悔）',example:{ja:'もっと早く気づけばよかった。',zh:'要是早點察覺就好了。',highlight:'気づけばよかった'},tip:'「ばよかった」表後悔已發生的事；「ばいい」是建議，不含後悔語意。',quiz:{blank:'ばよかった',distractors:['ばいい','てよかった','ばならない']}},{id:'n4-g129',pattern:'〜たらどうですか',connection:'動詞た形 ＋ らどうですか',meaning:'〜如何？（建議）',example:{ja:'一度、警察に相談したらどうですか。',zh:'要不要找警察商量看看？',highlight:'相談したらどうですか'},tip:'「たらどうですか」為建議，更禮貌說「たらいかがですか」；不能對上司直接使用。',quiz:{blank:'たらどうですか',distractors:['てもいいですか','たほうがどうですか','ながらどうですか']}},{id:'n4-g130',pattern:'〜たらいい',connection:'動詞た形 ＋ らいい',meaning:'〜就好了；〜比較好',example:{ja:'どこで待ったらいいですか。',zh:'我該在哪裡等才好呢？',highlight:'待ったらいい'},tip:'「たらいいですか」常用於詢問建議；「ばいい」「といい」意思相近但語感略異。',quiz:{blank:'たらいい',distractors:['てもいい','たほうが','たがる']}},{id:'n4-g131',pattern:'〜ばいい',connection:'動詞ば形 ＋ いい',meaning:'只要〜就好；〜就行了',example:{ja:'分からなければ、先生に聞けばいい。',zh:'不懂的話，問老師就行了。',highlight:'聞けばいい'},tip:'「ばいい」＝只要〜就好，表最簡單的方法；問句「どうすればいいですか」很常考。',quiz:{blank:'ばいい',distractors:['ばよかった','てはいけない','なさい']}},{id:'n4-g132',pattern:'〜といい',connection:'動詞辭書形 ＋ といい',meaning:'〜比較好；希望〜',example:{ja:'明日、晴れるといいですね。',zh:'希望明天會放晴呢。',highlight:'晴れるといい'},tip:'「といい」可表建議或希望，表希望時常接「ですね／のに」；不用於過去事實。',quiz:{blank:'といい',distractors:['ばいい','たらいい','てもいい']}},{id:'n4-g133',pattern:'〜ばいいのに',connection:'動詞ば形 ＋ いいのに',meaning:'要是〜就好了（遺憾、建議）',example:{ja:'そんなに痛いなら、病院に行けばいいのに。',zh:'那麼痛的話，去醫院不就好了。',highlight:'行けばいいのに'},tip:'「ばいいのに」表對他人行為的遺憾或不滿建議；主語通常不是說話者自己。',quiz:{blank:'ばいいのに',distractors:['ばいいので','ばいいため','てはいけないのに']}},{id:'n4-g134',pattern:'〜なくてはいけない',connection:'動詞ない形去い ＋ くてはいけない',meaning:'必須〜',example:{ja:'証拠を見つけなくてはいけない。',zh:'必須找到證據。',highlight:'見つけなくてはいけない'},tip:'「なくてはいけない」＝必須；同義有「なければならない」「ないといけない」。',quiz:{blank:'なくてはいけない',distractors:['なくてもいい','ないではいけない','なければいい']}},{id:'n4-g135',pattern:'〜ないといけない',connection:'動詞ない形 ＋ といけない',meaning:'必須〜；不〜不行',example:{ja:'もう帰らないといけない。',zh:'我得回去了。',highlight:'帰らないといけない'},tip:'「ないといけない」比「なければならない」口語；注意別與「てはいけない（禁止）」混淆。',quiz:{blank:'ないといけない',distractors:['なくてもいい','ないといい','てはいけない']}},{id:'n4-g136',pattern:'〜なきゃ／〜なくちゃ',connection:'動詞ない形去い ＋ きゃ／くちゃ',meaning:'得〜才行（口語）',example:{ja:'急がなきゃ、電車に遅れる。',zh:'得快點，不然趕不上電車。',highlight:'急がなきゃ'},tip:'「なきゃ」＝なければ，「なくちゃ」＝なくては，皆為口語，後面常省略いけない。',quiz:{blank:'なきゃ',distractors:['なくても','ないので','なければいい']}},{id:'n4-g137',pattern:'〜てはだめだ',connection:'動詞て形 ＋ はだめだ',meaning:'不可以〜',example:{ja:'現場の物に触ってはだめだ。',zh:'不可以碰現場的東西。',highlight:'触ってはだめだ'},tip:'「てはだめだ」＝禁止，同「てはいけない」；口語縮約為「ちゃだめ／じゃだめ」。',quiz:{blank:'てはだめだ',distractors:['てもいい','たほうがいい','てみたい']}},{id:'n4-g138',pattern:'〜ちゃだめ',connection:'動詞て形去て ＋ ちゃだめ（で→じゃだめ）',meaning:'不可以〜（口語）',example:{ja:'ここで遊んじゃだめだよ。',zh:'不可以在這裡玩喔。',highlight:'遊んじゃだめ'},tip:'「ては→ちゃ」「では→じゃ」：遊んで→遊んじゃだめ。撥音便、が行動詞要用じゃ。',quiz:{blank:'じゃだめ',distractors:['ちゃだめ','でもいい','じゃった']}},{id:'n4-g139',pattern:'〜なさい',connection:'動詞ます形 ＋ なさい',meaning:'給我〜；〜吧（命令）',example:{ja:'早く寝なさい。',zh:'快去睡覺。',highlight:'寝なさい'},tip:'「なさい」多用於上對下（父母對小孩、試題指示），對長輩不可使用。',quiz:{blank:'なさい',distractors:['ないで','たがる','ながら']}},{id:'n4-g140',pattern:'〜ろ／〜え（命令形）',connection:'五段動詞語尾改え段；一段動詞語幹 ＋ ろ',meaning:'〜！（命令）',example:{ja:'止まれ！動くな！',zh:'站住！不准動！',highlight:'止まれ'},tip:'命令形：五段語尾改え段（行け），一段＋ろ（見ろ），する→しろ，来る→来い。',quiz:{blank:'れ',distractors:['ろ','り','らない']}},{id:'n4-g141',pattern:'〜な（禁止）',connection:'動詞辭書形 ＋ な',meaning:'不准〜',example:{ja:'ここに入るな。',zh:'不准進來這裡。',highlight:'入るな'},tip:'禁止「辭書形＋な」語氣強硬；別與ます形＋な（なさい的省略，如「早く寝な」）混淆。',quiz:{blank:'な',distractors:['ね','よ','ぞ']}},{id:'n4-g142',pattern:'〜（よ）う（意向形）',connection:'動詞意向形',meaning:'〜吧（常體的邀約、意志）',example:{ja:'一緒に犯人を探そう。',zh:'一起找犯人吧。',highlight:'探そう'},tip:'意向形：五段改お段＋う（探そう），一段＋よう（見よう），する→しよう，来る→来よう。',quiz:{blank:'そう',distractors:['せ','す','さない']}},{id:'n4-g143',pattern:'〜（よ）うか',connection:'動詞意向形 ＋ か',meaning:'要不要〜呢；我來〜吧',example:{ja:'そろそろ帰ろうか。',zh:'差不多該回去了吧？',highlight:'帰ろうか'},tip:'「（よ）うか」可表提議「〜吧？」或主動提出「我來〜吧」；回答常用「うん、そうしよう」。',quiz:{blank:'ろうか',distractors:['れか','ったか','りか']}},{id:'n4-g144',pattern:'〜（よ）うと思っている',connection:'動詞意向形 ＋ と思っている',meaning:'一直打算〜',example:{ja:'来年、日本に留学しようと思っている。',zh:'我一直打算明年去日本留學。',highlight:'留学しようと思っている'},tip:'「（よ）うと思っている」表持續一段時間的打算；第三人稱也可用，「と思う」只限說話者當下。',quiz:{blank:'ようと思っている',distractors:['ると思っている','ようにしている','よう思っている']}},{id:'n4-g145',pattern:'〜ないつもりだ',connection:'動詞ない形 ＋ つもりだ',meaning:'打算不〜',example:{ja:'もう二度とあの店には行かないつもりだ。',zh:'我打算再也不去那家店了。',highlight:'行かないつもりだ'},tip:'否定的打算用「ないつもりだ」；「つもりはない」語氣更強，表完全沒有那個意思。',quiz:{blank:'ないつもりだ',distractors:['ないはずだ','ないそうだ','なかったつもりだ']}},{id:'n4-g146',pattern:'〜予定だ',connection:'動詞辭書形 ＋ 予定だ；名詞 ＋ の ＋ 予定だ',meaning:'預定〜',example:{ja:'会議は三時に始まる予定だ。',zh:'會議預定三點開始。',highlight:'始まる予定だ'},tip:'「予定だ」表已排定的計畫，非個人意志；「つもりだ」表個人打算，主語須為人。',quiz:{blank:'予定だ',distractors:['つもりだ','ことだ','ばかりだ']}},{id:'n4-g147',pattern:'〜ように（願望）',connection:'動詞ます形 ＋ ますように',meaning:'希望〜（祈願）',example:{ja:'事件が早く解決しますように。',zh:'希望案件能早日解決。',highlight:'解決しますように'},tip:'「ますように」表祈願，常用於祈禱、祝福；否定為「ませんように」。',quiz:{blank:'ますように',distractors:['ませんように','ましたように','ようにします']}},{id:'n4-g148',pattern:'〜ように言う',connection:'動詞辭書形／ない形 ＋ ように言う',meaning:'叫（某人）〜（間接命令）',example:{ja:'先生に早く帰るように言われた。',zh:'老師叫我早點回家。',highlight:'帰るように言われた'},tip:'「ように言う」為間接轉述命令或請求；被動「ように言われた」表被人叫去做。',quiz:{blank:'ように言われた',distractors:['ようと言われた','そうに言われた','ように言った']}},{id:'n4-g149',pattern:'〜ようにしている',connection:'動詞辭書形／ない形 ＋ ようにしている',meaning:'盡量（習慣性地）〜',example:{ja:'毎日、野菜を食べるようにしている。',zh:'我盡量每天吃蔬菜。',highlight:'食べるようにしている'},tip:'「ようにしている」表平常努力保持的習慣；「ようになる」表能力或狀態的變化。',quiz:{blank:'ようにしている',distractors:['ようとしている','ようにしてある','そうにしている']}},{id:'n4-g150',pattern:'〜なくなる',connection:'動詞ない形去い ＋ くなる',meaning:'變得不〜',example:{ja:'最近、彼はあまり笑わなくなった。',zh:'他最近變得不太笑了。',highlight:'笑わなくなった'},tip:'「なくなる」表從做到不做的變化；肯定的變化用「ようになる」。',quiz:{blank:'なくなった',distractors:['ないになった','なくてなった','ないくなった']}},{id:'n4-g151',pattern:'〜に来る（目的）',connection:'動詞ます形／動作名詞 ＋ に来る',meaning:'來〜（目的）',example:{ja:'忘れ物を取りに来ました。',zh:'我來拿忘記的東西。',highlight:'取りに来ました'},tip:'「ます形／動作名詞＋に来る・行く」表移動目的；ます形後直接接に，不加の。',quiz:{blank:'に',distractors:['で','を','へ']}},{id:'n4-g152',pattern:'〜のに（用途）',connection:'動詞辭書形 ＋ のに',meaning:'用於〜；〜要（用途、所需）',example:{ja:'この箱は手紙をしまうのに使っている。',zh:'這個盒子用來收信。',highlight:'しまうのに使っている'},tip:'用途的「のに」後接「使う・必要だ・便利だ」等；別與逆接的「のに（卻）」混淆。',quiz:{blank:'のに',distractors:['ので','のを','のが']}},{id:'n4-g153',pattern:'〜ために（原因）',connection:'普通形（名詞＋の）＋ ために',meaning:'因為〜（原因）',example:{ja:'事故のために、電車が遅れた。',zh:'因為事故，電車誤點了。',highlight:'事故のために'},tip:'原因「ために」語氣較正式，後句多為已發生的結果；目的用法則接意志動詞辭書形。',quiz:{blank:'のために',distractors:['のように','なのに','ので']}},{id:'n4-g154',pattern:'〜と（發現）',connection:'動詞辭書形 ＋ と ＋ 〜た',meaning:'一〜就發現〜',example:{ja:'部屋に入ると、男が倒れていた。',zh:'一走進房間，就發現有個男人倒在地上。',highlight:'部屋に入ると'},tip:'發現的「と」後句為過去式，表做了某事後發現的情況；後句不能接意志動作。',quiz:{blank:'と',distractors:['ても','ながら','から']}},{id:'n4-g155',pattern:'〜たら（發現）',connection:'動詞た形 ＋ ら ＋ 〜た',meaning:'〜之後（發現）〜',example:{ja:'引き出しを開けたら、古い手紙が出てきた。',zh:'打開抽屜後，發現了一封舊信。',highlight:'開けたら'},tip:'「たら〜た」表做了某事後意外發現；與「と〜た」意思相近，可互換。',quiz:{blank:'たら',distractors:['ても','ば','ないで']}},{id:'n4-g156',pattern:'〜ても（疑問詞）',connection:'疑問詞 ＋ 動詞て形 ＋ も',meaning:'無論〜都〜',example:{ja:'何度聞いても、彼は答えなかった。',zh:'不管問了多少次，他都沒回答。',highlight:'何度聞いても'},tip:'「疑問詞＋ても」＝無論〜都；如「いくら〜ても」「何度〜ても」「どんなに〜ても」。',quiz:{blank:'ても',distractors:['でも','たり','てから']}},{id:'n4-g157',pattern:'〜ても〜ても',connection:'動詞て形 ＋ も、動詞て形 ＋ も',meaning:'不管怎麼〜都〜',example:{ja:'探しても探しても、鍵が見つからない。',zh:'找了又找，鑰匙就是找不到。',highlight:'探しても探しても'},tip:'重複「〜ても〜ても」強調再怎麼做也沒有結果，後句多為否定或負面。',quiz:{blank:'ても探しても',distractors:['たら探したら','て探して','ながら探しながら']}},{id:'n4-g158',pattern:'〜も〜ば〜も',connection:'名詞 ＋ も ＋ 動詞ば形、名詞 ＋ も ＋ 〜',meaning:'既〜又〜（並列）',example:{ja:'あの人は英語も話せばフランス語も話せる。',zh:'那個人既會說英文也會說法文。',highlight:'英語も話せばフランス語も'},tip:'「AもBばCも」表並列「既〜又〜」，用於列舉同類事物；屬較書面的說法。',quiz:{blank:'ば',distractors:['し','なら','ので']}},{id:'n4-g159',pattern:'〜し',connection:'普通形 ＋ し',meaning:'又〜又〜；因為〜（列舉理由）',example:{ja:'この店は安いし、おいしいし、よく来る。',zh:'這家店又便宜又好吃，所以我常來。',highlight:'安いし、おいしいし'},tip:'「し」列舉理由，暗示還有其他理由；常以「〜し、〜し、（だから）」連用。',quiz:{blank:'し、おいしいし',distractors:['ても、おいしいても','のに、おいしいのに','けど、おいしいけど']}},{id:'n4-g160',pattern:'〜ので',connection:'普通形（な形・名詞＋な）＋ ので',meaning:'因為〜（客觀原因）',example:{ja:'道が混んでいたので、遅れました。',zh:'因為路上塞車，所以遲到了。',highlight:'混んでいたので'},tip:'「ので」比「から」客觀、禮貌；後句不宜接強烈命令。名詞・な形要用「なので」。',quiz:{blank:'ので',distractors:['のに','けど','ても']}},{id:'n4-g161',pattern:'〜て（原因）',connection:'動詞て形／形容詞て形 ＋ 〜',meaning:'因為〜（而〜）',example:{ja:'ニュースを聞いて、驚きました。',zh:'聽到新聞嚇了一跳。',highlight:'聞いて、驚きました'},tip:'「て」表原因時後句多為感情或無意志結果（驚く・困る）；不能接命令、請求。',quiz:{blank:'て',distractors:['で','たり','ながら']}},{id:'n4-g162',pattern:'〜なくて（原因）',connection:'動詞ない形去い ＋ くて',meaning:'因為沒有〜（而〜）',example:{ja:'犯人が見つからなくて、困っている。',zh:'因為找不到犯人而傷腦筋。',highlight:'見つからなくて'},tip:'原因用「なくて」，後接感情或結果（困る・残念）；「ないで」表附帶或替代，不表原因。',quiz:{blank:'なくて',distractors:['ないのに','なければ','ないなら']}},{id:'n4-g163',pattern:'〜けど／〜けれど',connection:'普通形 ＋ けど／けれど',meaning:'雖然〜但是〜',example:{ja:'調べたけど、何も分からなかった。',zh:'雖然調查過了，卻什麼也沒查出來。',highlight:'調べたけど'},tip:'「けど」比「けれど／けれども」更口語；也可用於句尾委婉表達。',quiz:{blank:'けど',distractors:['ので','から','し']}},{id:'n4-g164',pattern:'〜ないで（代替）',connection:'動詞ない形 ＋ で',meaning:'不〜而〜（替代）',example:{ja:'バスに乗らないで、歩いて行った。',zh:'沒搭公車，而是走路去了。',highlight:'乗らないで'},tip:'「ないで（替代）」＝不做A而做B；「なくて」表原因，考題常比較這兩者。',quiz:{blank:'ないで',distractors:['なくて','ずで','ないと']}},{id:'n4-g165',pattern:'〜かどうか',connection:'普通形（な形・名詞去だ）＋ かどうか',meaning:'是否〜',example:{ja:'彼の話が本当かどうか、確かめよう。',zh:'確認一下他說的是否屬實吧。',highlight:'本当かどうか'},tip:'「かどうか」用於沒有疑問詞的間接疑問；有疑問詞時只用「か」。名詞・な形不加だ。',quiz:{blank:'かどうか',distractors:['かどうして','だどうか','とどうか']}},{id:'n4-g166',pattern:'〜か（間接疑問）',connection:'疑問詞 ＋ 普通形 ＋ か',meaning:'（嵌入句中的疑問）',example:{ja:'犯人がどこに逃げたか分かりません。',zh:'不知道犯人逃到哪裡去了。',highlight:'どこに逃げたか'},tip:'有疑問詞的間接疑問句用「疑問詞＋普通形＋か」；名詞・な形不加だ：誰か分からない。',quiz:{blank:'たか',distractors:['たを','たと','たで']}},{id:'n4-g167',pattern:'〜のは〜だ',connection:'普通形 ＋ のは ＋ 名詞 ＋ だ',meaning:'〜的是〜（強調）',example:{ja:'窓を開けたのは、この男だ。',zh:'打開窗戶的就是這個男人。',highlight:'開けたのは、この男だ'},tip:'「〜のは〜だ」強調句，把焦點放在後面；名詞化時用の不用こと。',quiz:{blank:'のは',distractors:['のを','のに','ので']}},{id:'n4-g168',pattern:'〜のを（名詞化）',connection:'普通形 ＋ のを',meaning:'把〜這件事（名詞化）',example:{ja:'鍵をかけるのを忘れた。',zh:'我忘了鎖門。',highlight:'かけるのを忘れた'},tip:'「忘れる・見る・聞く・手伝う」前名詞化多用「の」；「見る・聞く」只能用の。',quiz:{blank:'のを',distractors:['のが','のに','ので']}},{id:'n4-g169',pattern:'〜こと（名詞化）',connection:'動詞辭書形 ＋ こと',meaning:'〜這件事（名詞化）',example:{ja:'私の趣味は推理小説を読むことです。',zh:'我的興趣是看推理小說。',highlight:'読むことです'},tip:'「〜ことです」常用於說明興趣、夢想；句尾「〜です」前只能用こと，不能用の。',quiz:{blank:'こと',distractors:['もの','ところ','ほう']}},{id:'n4-g170',pattern:'〜という',connection:'名詞 ＋ という ＋ 名詞',meaning:'叫做〜的〜',example:{ja:'田中という人から電話がありました。',zh:'有一位叫田中的人打電話來。',highlight:'田中という人'},tip:'「AというB」＝叫做A的B，用於對方可能不認識的事物；口語可說「Aって」。',quiz:{blank:'という',distractors:['とする','との','といって']}},{id:'n4-g171',pattern:'〜って（話題）',connection:'名詞 ＋ って',meaning:'〜是指（提出話題，口語）',example:{ja:'密室って、どういう意味ですか。',zh:'密室是什麼意思？',highlight:'密室って'},tip:'「って」口語中可代替「は」或「というのは」來提出話題，也可表轉述。',quiz:{blank:'って',distractors:['しか','まで','ほど']}},{id:'n4-g172',pattern:'〜と同じ',connection:'名詞 ＋ と同じ',meaning:'和〜一樣',example:{ja:'犯人は私と同じ靴を履いていた。',zh:'犯人穿著跟我一樣的鞋子。',highlight:'私と同じ'},tip:'「Aと同じ」修飾名詞時直接接名詞，不加の或な：同じ靴（×同じな靴）。',quiz:{blank:'と同じ',distractors:['に同じ','が同じ','を同じ']}},{id:'n4-g173',pattern:'〜に似ている',connection:'名詞 ＋ に似ている',meaning:'和〜很像',example:{ja:'この筆跡は彼の字に似ている。',zh:'這筆跡跟他的字很像。',highlight:'彼の字に似ている'},tip:'「に似ている」表狀態，常用ている形；說「似る」單用較少。也可說「と似ている」。',quiz:{blank:'に似ている',distractors:['を似ている','が似ている','で似ている']}},{id:'n4-g174',pattern:'〜ほど〜ない',connection:'名詞 ＋ ほど ＋ 形容詞否定',meaning:'沒有〜那麼〜',example:{ja:'今年の夏は去年ほど暑くない。',zh:'今年夏天沒有去年那麼熱。',highlight:'去年ほど暑くない'},tip:'「AはBほど〜ない」必須接否定；肯定比較用「AはBより〜」。',quiz:{blank:'ほど',distractors:['まで','しか','ばかり']}},{id:'n4-g175',pattern:'〜がする',connection:'名詞（音・におい・味・声）＋ がする',meaning:'感覺到〜（聲音、氣味等）',example:{ja:'台所から変なにおいがする。',zh:'廚房傳來奇怪的味道。',highlight:'においがする'},tip:'「がする」用於聲音、氣味、味道、感覺（気がする），表透過感官自然感受到。',quiz:{blank:'がする',distractors:['をする','にする','でする']}},{id:'n4-g176',pattern:'〜さ（名詞化）',connection:'い形容詞去い／な形容詞語幹 ＋ さ',meaning:'〜度；〜的程度',example:{ja:'この箱の重さを量ってください。',zh:'請量一下這個箱子的重量。',highlight:'重さ'},tip:'「さ」把形容詞名詞化表程度；「み」表感受（重み・楽しみ），可接的詞較少。',quiz:{blank:'さを',distractors:['いを','くを','なを']}},{id:'n4-g177',pattern:'〜でも（例示）',connection:'名詞 ＋ でも',meaning:'〜之類的（舉例、委婉）',example:{ja:'お茶でも飲みませんか。',zh:'要不要喝杯茶什麼的？',highlight:'お茶でも'},tip:'「でも」舉例並帶委婉語氣，常用於邀約：「お茶でも飲みませんか」。',quiz:{blank:'でも',distractors:['しか','ほど','まで']}},{id:'n4-g178',pattern:'疑問詞＋でも',connection:'疑問詞 ＋ でも',meaning:'無論〜都〜',example:{ja:'この問題なら誰でも解ける。',zh:'這個問題誰都解得開。',highlight:'誰でも'},tip:'「疑問詞＋でも」＝全面肯定（誰でも）；「疑問詞＋も＋否定」＝全面否定。',quiz:{blank:'でも',distractors:['か','しか','まで']}},{id:'n4-g179',pattern:'疑問詞＋か',connection:'疑問詞 ＋ か',meaning:'某〜（不確定）',example:{ja:'誰かが窓から入ったようだ。',zh:'好像有人從窗戶進來了。',highlight:'誰か'},tip:'「疑問詞＋か」表不確定的某物（誰か・何か・どこか），與「も」「でも」的意思不同。',quiz:{blank:'かが',distractors:['もが','にが','までが']}},{id:'n4-g180',pattern:'疑問詞＋も〜ない',connection:'疑問詞 ＋ も ＋ 否定',meaning:'什麼〜都不〜',example:{ja:'その夜は何も聞こえなかった。',zh:'那天晚上什麼也沒聽到。',highlight:'何も聞こえなかった'},tip:'「疑問詞＋も」後必須接否定＝全面否定；「何か」表不確定的某物。',quiz:{blank:'も',distractors:['か','しか','まで']}},{id:'n4-g181',pattern:'〜ずつ',connection:'數量詞 ＋ ずつ',meaning:'每〜；各〜',example:{ja:'一人ずつ部屋に入ってください。',zh:'請一個一個進入房間。',highlight:'一人ずつ'},tip:'「數量詞＋ずつ」表平均分配或每次相同數量：少しずつ・一つずつ。',quiz:{blank:'ずつ',distractors:['だけ','まで','しか']}},{id:'n4-g182',pattern:'〜目',connection:'數量詞 ＋ 目',meaning:'第〜',example:{ja:'右から三つ目の箱を開けてください。',zh:'請打開從右邊數來第三個箱子。',highlight:'三つ目'},tip:'「數量詞＋目」表順序第幾個：三つ目・二回目・一番目；單純數量不加目。',quiz:{blank:'目',distractors:['個','番','回']}}]},1921,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N4_READING",{enumerable:!0,get:function(){return n}});const n=[{id:"n4-r01",title:"初めての一人暮らし",titleZh:"第一次一個人住",topic:"生活",paragraphs:[{ja:"今年の春から、私は大学に通うために一人で住んでいます。前は家族と一緒に住んでいたので、料理も洗濯も母がしてくれました。でも今は、全部自分でしなければなりません。",zh:"從今年春天開始，我為了上大學而一個人住。以前和家人一起住，所以做飯和洗衣服都是媽媽幫我做的。但是現在，全部都得自己來。"},{ja:"最初の一か月は大変でした。朝ご飯を作る時間がなくて、コンビニでパンを買うことが多かったです。お金もすぐになくなってしまいました。",zh:"最初的一個月很辛苦。沒有時間做早餐，常常在便利商店買麵包。錢也很快就花光了。"},{ja:"それで、週末にスーパーで野菜や肉をまとめて買って、一週間分のおかずを作っておくことにしました。そうすると、毎朝お弁当も持って行けるようになりました。",zh:"所以，我決定週末在超市一次買好蔬菜和肉，先做好一個星期份的配菜。這樣一來，每天早上也能帶便當出門了。"},{ja:"一人暮らしは大変ですが、自分でできることが増えて、うれしいです。今度母に会ったら、私が作ったカレーを食べてもらいたいと思っています。",zh:"一個人住雖然辛苦，但自己會做的事情變多了，很開心。下次見到媽媽的時候，我想請她吃我做的咖哩。"}],vocab:[{word:"一人暮らし",reading:"ひとりぐらし",meaning:"一個人住、獨居"},{word:"洗濯",reading:"せんたく",meaning:"洗衣服"},{word:"大変",reading:"たいへん",meaning:"辛苦、不得了"},{word:"週末",reading:"しゅうまつ",meaning:"週末"},{word:"野菜",reading:"やさい",meaning:"蔬菜"},{word:"弁当",reading:"べんとう",meaning:"便當"},{word:"増える",reading:"ふえる",meaning:"增加"}],questions:[{question:"最初の一か月、この人は朝ご飯をどうしていましたか。",questionZh:"最初的一個月，這個人的早餐是怎麼解決的？",options:["コンビニでパンを買うことが多かった","母が毎朝作ってくれた","毎朝自分でカレーを作った","朝ご飯は何も食べなかった"]},{question:"今、この人は週末に何をしていますか。",questionZh:"現在，這個人週末在做什麼？",options:["一週間分のおかずを作っておく","実家に帰って母に会う","コンビニでアルバイトをする","友だちとレストランに行く"]}]},{id:"n4-r02",title:"父の自転車通勤",titleZh:"爸爸騎腳踏車上班",topic:"生活",paragraphs:[{ja:"私の父は、前は会社まで電車で通っていました。でも、去年の秋から自転車で通うようになりました。家から会社までは、自転車で四十分ぐらいかかります。",zh:"我爸爸以前都搭電車去公司。但是從去年秋天開始，他改成騎腳踏車通勤。從家裡到公司，騎腳踏車大約要四十分鐘。"},{ja:"父が自転車を始めた理由は、医者に「もう少し運動したほうがいいですよ」と言われたからです。父は毎日忙しくて、ジムに行く時間がありませんでした。",zh:"爸爸開始騎腳踏車的原因，是醫生對他說「最好再多運動一點喔」。爸爸每天都很忙，沒有時間去健身房。"},{ja:"初めは、会社に着くと疲れてしまって、仕事ができないと言っていました。しかし、二か月ぐらいたつと、体が軽くなって、夜もよく眠れるようになったそうです。電車代も払わなくていいので、母も喜んでいます。",zh:"一開始，他說到了公司就累壞了，沒辦法工作。但是過了大約兩個月，聽說身體變輕盈了，晚上也睡得很好。因為也不用付電車費，媽媽也很高興。"},{ja:"ただ、雨の日は危ないので、電車を使います。父は「天気がいい日に風の中を走るのは気持ちがいい」と言って、今では週末も自転車で出かけています。",zh:"不過，下雨天很危險，所以會搭電車。爸爸說「天氣好的日子在風中騎車很舒服」，現在連週末也騎腳踏車出門。"}],vocab:[{word:"通う",reading:"かよう",meaning:"（定期）往返、通勤、上學"},{word:"理由",reading:"りゆう",meaning:"理由、原因"},{word:"医者",reading:"いしゃ",meaning:"醫生"},{word:"運動",reading:"うんどう",meaning:"運動"},{word:"疲れる",reading:"つかれる",meaning:"疲累"},{word:"眠る",reading:"ねむる",meaning:"睡覺、入睡"},{word:"危ない",reading:"あぶない",meaning:"危險的"}],questions:[{question:"父が自転車で会社に通うようになったのはどうしてですか。",questionZh:"爸爸為什麼開始騎腳踏車去公司？",options:["医者にもっと運動したほうがいいと言われたから","電車がこんでいるのがきらいだったから","会社が家の近くに引っ越したから","母に電車代が高いと言われたから"]},{question:"雨の日、父はどうやって会社へ行きますか。",questionZh:"下雨天，爸爸怎麼去公司？",options:["電車で行く","自転車で行く","会社を休む","母に車で送ってもらう"]}]},{id:"n4-r03",title:"お正月のおせち料理",titleZh:"新年的年菜",topic:"文化",paragraphs:[{ja:"日本では、一月一日から三日ごろまでを「お正月」と言います。お正月には、家族が集まって、「おせち料理」という特別な料理を食べる習慣があります。",zh:"在日本，一月一日到三日左右稱為「正月」。正月時，有家人聚在一起吃一種叫做「御節料理」的特別料理的習俗。"},{ja:"おせち料理は、きれいな箱に入っています。中の料理には、一つ一つ意味があります。たとえば、えびは腰が曲がるまで長く生きられるように、黒豆はまじめに元気に働けるように、という願いがあるそうです。",zh:"年菜裝在漂亮的盒子裡。裡面的料理每一樣都有意義。例如，蝦子代表希望能長壽到腰都彎了，黑豆則代表希望能認真又健康地工作。"},{ja:"昔は、お正月の間は台所の仕事を休むために、年末に家で料理をたくさん作っておきました。おせち料理に、何日か置いておいても悪くならない料理が多いのは、そのためです。",zh:"以前，為了在正月期間不必做廚房的工作，人們會在年底先在家裡做好很多料理。年菜裡有很多放了好幾天也不會壞的料理，就是這個原因。"},{ja:"最近は、自分で作らないで、デパートやインターネットで買う家も増えています。でも、家族で新しい年のことを話しながら食べる時間は、今も大切にされています。",zh:"最近，不自己做、而是在百貨公司或網路上購買的家庭也越來越多。不過，全家人一邊聊新的一年一邊吃飯的時光，現在依然很受重視。"}],vocab:[{word:"正月",reading:"しょうがつ",meaning:"新年、正月"},{word:"特別",reading:"とくべつ",meaning:"特別"},{word:"習慣",reading:"しゅうかん",meaning:"習慣、習俗"},{word:"意味",reading:"いみ",meaning:"意思、意義"},{word:"台所",reading:"だいどころ",meaning:"廚房"},{word:"最近",reading:"さいきん",meaning:"最近"},{word:"大切",reading:"たいせつ",meaning:"重要、珍惜"}],questions:[{question:"昔、おせち料理を年末に作っておいたのはどうしてですか。",questionZh:"以前為什麼要在年底先做好年菜？",options:["お正月の間、台所の仕事を休むため","年末のほうが野菜が安かったから","子どもたちが料理を手伝いたかったから","お正月は箱が買えなかったから"]},{question:"文章の内容と合っているものはどれですか。",questionZh:"下列哪一項符合文章內容？",options:["最近はおせち料理を買う家も増えている","おせち料理の中の料理には意味がない","おせち料理は一月の終わりに食べる","おせち料理にはすぐに悪くなる料理が多い"]}]},{id:"n4-r04",title:"初めての銭湯",titleZh:"第一次去澡堂",topic:"文化",paragraphs:[{ja:"先週、日本人の友だちに誘われて、初めて銭湯に行きました。銭湯は町の中にある大きなお風呂で、お金を払えばだれでも入ることができます。",zh:"上星期，我被日本朋友邀請，第一次去了錢湯（公共澡堂）。錢湯是位在城鎮裡的大浴池，只要付錢，誰都可以進去泡。"},{ja:"入る前に、友だちがいくつかのルールを教えてくれました。お湯に入る前に、体を洗わなければなりません。それから、タオルをお湯の中に入れてはいけません。髪が長い人は、髪をまとめておきます。",zh:"進去之前，朋友教了我幾個規則。進熱水池之前，一定要先洗身體。還有，不可以把毛巾放進熱水裡。頭髮長的人要先把頭髮綁起來。"},{ja:"最初は、知らない人といっしょにお風呂に入るのが恥ずかしかったです。でも、お湯がとても気持ちよくて、すぐに慣れました。となりにいたおじいさんが私の国のことをいろいろ聞いてくれて、楽しかったです。",zh:"一開始，和不認識的人一起泡澡讓我覺得很害羞。但是熱水非常舒服，我很快就習慣了。旁邊的老爺爺問了我很多關於我國家的事，很開心。"},{ja:"お風呂から出たあとで、友だちと冷たい牛乳を飲みました。それも銭湯の楽しみの一つだそうです。来月もまた行こうと約束しました。",zh:"泡完澡出來以後，我和朋友喝了冰牛奶。聽說那也是去錢湯的樂趣之一。我們約好下個月還要再去。"}],vocab:[{word:"誘う",reading:"さそう",meaning:"邀請、邀約"},{word:"銭湯",reading:"せんとう",meaning:"公共澡堂"},{word:"払う",reading:"はらう",meaning:"付（錢）"},{word:"髪",reading:"かみ",meaning:"頭髮"},{word:"恥ずかしい",reading:"はずかしい",meaning:"害羞的、丟臉的"},{word:"慣れる",reading:"なれる",meaning:"習慣、適應"},{word:"約束",reading:"やくそく",meaning:"約定"}],questions:[{question:"銭湯でしてはいけないことは何ですか。",questionZh:"在錢湯不可以做的事情是什麼？",options:["タオルをお湯の中に入れること","お湯に入る前に体を洗うこと","長い髪をまとめること","となりの人と話すこと"]},{question:"お風呂から出たあとで、二人は何をしましたか。",questionZh:"泡完澡出來以後，兩個人做了什麼？",options:["冷たい牛乳を飲んだ","おじいさんの家に行った","もう一度お風呂に入った","温かいお茶を飲んだ"]}]},{id:"n4-r05",title:"子ども食堂",titleZh:"兒童食堂",topic:"社會",paragraphs:[{ja:"最近、日本のあちこちで「子ども食堂」が開かれています。子ども食堂は、子どもが安く、または無料で晩ご飯を食べられる場所です。お寺や町の小さな建物などを使っているところが多いです。",zh:"最近，日本各地都有人在開設「兒童食堂」。兒童食堂是讓孩子能便宜或免費吃晚餐的地方。很多是借用寺廟或鎮上的小建築物。"},{ja:"親が夜遅くまで働いている家では、子どもが一人で晩ご飯を食べることがあります。子ども食堂を始めた人たちは、子どもたちにみんなでいっしょに温かいご飯を食べてほしいと考えました。",zh:"在父母工作到很晚的家庭，有時孩子會一個人吃晚餐。開始經營兒童食堂的人們，希望孩子們能大家一起吃熱騰騰的飯。"},{ja:"料理を作るのは、近所に住んでいる人たちです。野菜は、近くの農家の人がくれることもあります。最近は、子どもだけでなく、一人で住んでいるお年寄りも来るようになりました。",zh:"做料理的是住在附近的人們。蔬菜有時是附近的農家送的。最近，不只是孩子，一個人住的老人家也開始會來了。"},{ja:"子ども食堂では、食事のあとで、大学生が宿題を見てあげることもあります。食べるだけではなく、町の人どうしが知り合う場所にもなっているのです。",zh:"在兒童食堂，吃完飯後有時也會有大學生幫忙看功課。這裡不只是吃飯的地方，也成為鎮上的人們彼此認識的場所。"}],vocab:[{word:"無料",reading:"むりょう",meaning:"免費"},{word:"晩ご飯",reading:"ばんごはん",meaning:"晚餐"},{word:"建物",reading:"たてもの",meaning:"建築物"},{word:"温かい",reading:"あたたかい",meaning:"溫暖的、熱的"},{word:"近所",reading:"きんじょ",meaning:"附近、鄰居"},{word:"お年寄り",reading:"おとしより",meaning:"老人家"},{word:"宿題",reading:"しゅくだい",meaning:"作業、功課"}],questions:[{question:"子ども食堂で料理を作っているのはだれですか。",questionZh:"在兒童食堂做料理的是誰？",options:["近所に住んでいる人たち","子どもたちの親","レストランのコック","大学の先生"]},{question:"子ども食堂について、文章の内容と合っているものはどれですか。",questionZh:"關於兒童食堂，下列哪一項符合文章內容？",options:["一人で住んでいるお年寄りも来るようになった","子どもしか入ることができない","料理の値段がとても高い","食事のあとはすぐに帰らなければならない"]}]},{id:"n4-r06",title:"買い物袋を持って行こう",titleZh:"帶著購物袋出門吧",topic:"社會",paragraphs:[{ja:"日本では、2020年から、店でもらうプラスチックの袋が有料になりました。それまでは、コンビニやスーパーで買い物をすると、袋を無料でもらうことができました。",zh:"在日本，從2020年開始，在店裡拿的塑膠袋改成要收費。在那之前，在便利商店或超市買東西時，可以免費拿到袋子。"},{ja:"袋が有料になったのは、プラスチックのごみを減らすためです。海に捨てられたプラスチックはなかなかなくならないので、魚や鳥が困っています。",zh:"袋子改成收費，是為了減少塑膠垃圾。被丟到海裡的塑膠很難消失，所以魚和鳥都深受其害。"},{ja:"今では、多くの人が自分の買い物袋を持って出かけるようになりました。小さくたためる袋が人気で、かばんの中にいつも入れている人もいます。私も最初はよく忘れましたが、今は玄関に置いておくので、忘れなくなりました。",zh:"現在，很多人都會帶著自己的購物袋出門。可以摺得很小的袋子很受歡迎，也有人一直把它放在包包裡。我一開始也常常忘記，但現在都先放在玄關，所以就不會忘了。"},{ja:"袋一枚は数円ですが、毎日のことなので、みんなで気をつければ大きな違いになります。小さなことから始めるのが大切だと思います。",zh:"一個袋子只要幾日圓，但因為是每天的事，大家一起注意的話就會帶來很大的差別。我認為從小事開始做起是很重要的。"}],vocab:[{word:"袋",reading:"ふくろ",meaning:"袋子"},{word:"有料",reading:"ゆうりょう",meaning:"收費"},{word:"減らす",reading:"へらす",meaning:"減少"},{word:"捨てる",reading:"すてる",meaning:"丟棄"},{word:"忘れる",reading:"わすれる",meaning:"忘記"},{word:"玄関",reading:"げんかん",meaning:"玄關"},{word:"違い",reading:"ちがい",meaning:"差別、不同"}],questions:[{question:"店の袋が有料になったのはどうしてですか。",questionZh:"店裡的袋子為什麼改成收費？",options:["プラスチックのごみを減らすため","店がもっとお金をもうけたかったから","袋を作る工場が少なくなったから","魚や鳥の食べ物にするため"]},{question:"「私」は今、どうやって買い物袋を忘れないようにしていますか。",questionZh:"「我」現在是怎麼避免忘記帶購物袋的？",options:["玄関に置いておく","かばんの中にいつも入れておく","店で毎回新しい袋を買う","家族に持ってきてもらう"]}]},{id:"n4-r07",title:"北へ進む桜",titleZh:"往北前進的櫻花",topic:"自然",paragraphs:[{ja:"日本の春といえば、桜です。桜の花は、毎年三月ごろに南の九州のほうから咲き始めて、だんだん北のほうへ進んでいきます。五月ごろには、北海道でも桜が見られます。",zh:"說到日本的春天，就是櫻花。櫻花每年三月左右從南方的九州一帶開始綻放，然後漸漸往北方前進。到了五月左右，在北海道也能看到櫻花。"},{ja:"桜が咲く日を地図の上で線にしたものを「桜前線」と言います。春になると、テレビのニュースは毎日のように「東京では来週咲きそうです」などと伝えます。",zh:"把櫻花開花的日期在地圖上連成線，就叫做「櫻花前線」。一到春天，電視新聞幾乎每天都會報導「東京好像下週就會開花」之類的消息。"},{ja:"桜の花が咲いている時間はとても短くて、一週間ぐらいで終わってしまいます。それで、人々は花が咲いている間に、公園や川のそばでお花見をします。",zh:"櫻花開花的時間非常短，大約一個星期就結束了。所以，人們會趁花開的期間，在公園或河邊賞花。"},{ja:"でも最近は、暖かい冬が多くなったので、昔より早く咲く年が増えています。反対に、南のほうでは冬が暖かすぎて、きれいに咲かないこともあるそうです。",zh:"但是最近溫暖的冬天變多了，所以比以前更早開花的年份越來越多。相反地，聽說在南方，有時因為冬天太溫暖，櫻花反而開得不漂亮。"}],vocab:[{word:"桜",reading:"さくら",meaning:"櫻花"},{word:"咲く",reading:"さく",meaning:"（花）開"},{word:"地図",reading:"ちず",meaning:"地圖"},{word:"伝える",reading:"つたえる",meaning:"傳達、報導"},{word:"短い",reading:"みじかい",meaning:"短的"},{word:"暖かい",reading:"あたたかい",meaning:"溫暖的"},{word:"反対",reading:"はんたい",meaning:"相反、反對"}],questions:[{question:"日本の桜は、どのように咲いていきますか。",questionZh:"日本的櫻花是怎麼樣依序開花的？",options:["南から北のほうへ咲いていく","北から南のほうへ咲いていく","日本中で同じ日に咲く","東京で最初に咲く"]},{question:"最近、桜についてどんなことが起きていますか。",questionZh:"最近，關於櫻花發生了什麼事？",options:["昔より早く咲く年が増えている","北海道では咲かなくなった","一か月ぐらい咲き続けるようになった","冬の間に咲くようになった"]}]},{id:"n4-r08",title:"頭のいいカラス",titleZh:"聰明的烏鴉",topic:"自然",paragraphs:[{ja:"町でよく見る黒い鳥、カラスは、とても頭がいい鳥だと言われています。ごみを出す日を覚えていて、その日の朝になると集まってくるカラスもいるそうです。",zh:"在城鎮裡常見的黑色鳥類——烏鴉，據說是非常聰明的鳥。聽說有些烏鴉記得倒垃圾的日子，一到那天早上就會聚集過來。"},{ja:"ある町では、カラスがかたいくるみを道に置いて、車にひかせて割る様子が見られました。信号が赤になって車が止まると、カラスは道に下りて、割れたくるみを食べるのです。",zh:"在某個城鎮，有人看到烏鴉把堅硬的核桃放在馬路上，讓車子輾過去把它壓破。等紅綠燈變紅、車子停下來時，烏鴉就飛到路上，吃掉裂開的核桃。"},{ja:"また、カラスは人の顔も覚えることができると言われています。自分にいやなことをした人を、何年もあとまで覚えていることもあるそうです。",zh:"另外，據說烏鴉也能記住人的臉。聽說牠們有時會把對自己做過討厭事情的人記上好幾年。"},{ja:"カラスはごみを散らかすので、きらいな人も多いでしょう。でも、よく見てみると、おもしろい鳥だとわかるかもしれません。",zh:"烏鴉會把垃圾弄得亂七八糟，所以討厭牠的人應該也很多吧。不過，仔細觀察看看的話，或許會發現牠是很有趣的鳥。"}],vocab:[{word:"覚える",reading:"おぼえる",meaning:"記住"},{word:"集まる",reading:"あつまる",meaning:"聚集"},{word:"道",reading:"みち",meaning:"道路"},{word:"割る",reading:"わる",meaning:"打破、弄破"},{word:"信号",reading:"しんごう",meaning:"紅綠燈、號誌"},{word:"止まる",reading:"とまる",meaning:"停止"},{word:"顔",reading:"かお",meaning:"臉"}],questions:[{question:"ある町のカラスは、どうやってくるみを食べましたか。",questionZh:"某個城鎮的烏鴉是怎麼吃核桃的？",options:["道に置いて、車にひかせて割った","高い木の上から落として割った","人からもらった割れたくるみを食べた","石でたたいて割った"]},{question:"文章によると、カラスについて正しいものはどれですか。",questionZh:"根據文章，關於烏鴉下列何者正確？",options:["人の顔を覚えることができる","ごみを出す日を知らない","赤い信号の時は道に下りない","夜しか町に来ない"]}]},{id:"n4-r09",title:"空はどうして青いのか",titleZh:"天空為什麼是藍色的",topic:"科學",paragraphs:[{ja:"晴れた日の空は青く、夕方の空は赤くなります。同じ空なのに、どうして色が変わるのでしょうか。",zh:"晴天的天空是藍色的，傍晚的天空則會變紅。明明是同一片天空，為什麼顏色會改變呢？"},{ja:"太陽の光は白く見えますが、本当はいろいろな色の光が集まってできています。光が空気の中を通るとき、青い光は空気にぶつかって、いろいろな方向に広がりやすいです。それで、昼間は空のどこを見ても青く見えるのです。",zh:"太陽的光看起來是白色的，但其實是由各種顏色的光聚集而成的。光通過空氣的時候，藍色的光容易撞到空氣，往各個方向散開。所以白天不管看天空的哪裡，看起來都是藍色的。"},{ja:"夕方になると、太陽が低くなるので、光は空気の中を長く通らなければなりません。その途中で、青い光は広がってしまい、私たちの目まで届きにくくなります。そして、赤い光が多く残るので、空が赤く見えるのです。",zh:"到了傍晚，太陽變低，光必須在空氣中穿過很長的距離。在途中，藍色的光已經散開了，很難到達我們的眼睛。然後剩下比較多的紅光，所以天空看起來是紅色的。"},{ja:"ふだん何も考えずに見ている空にも、ちゃんと理由があります。今度空を見るときは、光の旅のことを考えてみてください。",zh:"平常不經意看著的天空，其實也有它的道理。下次看天空的時候，請想一想光的旅程吧。"}],vocab:[{word:"晴れる",reading:"はれる",meaning:"放晴"},{word:"夕方",reading:"ゆうがた",meaning:"傍晚"},{word:"太陽",reading:"たいよう",meaning:"太陽"},{word:"光",reading:"ひかり",meaning:"光"},{word:"空気",reading:"くうき",meaning:"空氣"},{word:"途中",reading:"とちゅう",meaning:"途中、中途"},{word:"残る",reading:"のこる",meaning:"剩下、留下"}],questions:[{question:"昼間の空が青く見えるのはどうしてですか。",questionZh:"白天的天空為什麼看起來是藍色的？",options:["青い光が空気にぶつかって広がりやすいから","太陽の光が青い色だから","海の色が空にうつるから","空気そのものが青い色をしているから"]},{question:"夕方の空が赤く見えるのはどうしてですか。",questionZh:"傍晚的天空為什麼看起來是紅色的？",options:["光が空気の中を長く通って、赤い光が多く残るから","夕方の太陽は赤い光しか出さないから","夕方になると空気がなくなるから","夕方は青い光が強くなるから"]}]},{id:"n4-r10",title:"なくなったケーキ",titleZh:"消失的蛋糕",topic:"推理",paragraphs:[{ja:"日曜日の午後、田中さんの家で小さな事件が起きました。冷蔵庫に入れておいたいちごのケーキが、なくなってしまったのです。そのとき家にいたのは、兄の健、妹の花、そしておばあさんの三人でした。",zh:"星期天下午，田中家發生了一件小事件。放在冰箱裡的草莓蛋糕不見了。當時在家的是哥哥小健、妹妹小花和奶奶三個人。"},{ja:"近所に住んでいる探偵の森さんが、話を聞きに来ました。健は「ぼくは二時からずっと部屋でゲームをしていたよ」と言いました。花は「私は庭で犬と遊んでいたの」と言いました。おばあさんは「私は朝から一度も外に出ていませんよ。台所でお茶を飲んでいて、少し寝てしまいました」と言いました。",zh:"住在附近的偵探森先生來問話。小健說：「我從兩點開始就一直在房間裡打電動。」小花說：「我在院子裡跟狗狗玩。」奶奶說：「我從早上就一次都沒出門。我在廚房喝茶，不小心睡著了一下。」"},{ja:"森さんは台所を調べました。冷蔵庫のドアに、小さな手のあとが付いていました。手のあとは茶色くて、土で汚れていました。健の手は、森さんの手と同じぐらい大きいです。",zh:"森先生調查了廚房。冰箱門上留有小小的手印。手印是咖啡色的，沾滿了泥土。小健的手和森先生的手差不多大。"},{ja:"森さんはもう一度三人の顔を見て、「犯人がわかりましたよ」と言いました。そして、ある人の手をやさしく見ました。",zh:"森先生再看了一次三個人的臉，說：「我知道犯人是誰了。」然後，溫和地看著某個人的手。"}],vocab:[{word:"事件",reading:"じけん",meaning:"事件"},{word:"冷蔵庫",reading:"れいぞうこ",meaning:"冰箱"},{word:"探偵",reading:"たんてい",meaning:"偵探"},{word:"庭",reading:"にわ",meaning:"院子"},{word:"調べる",reading:"しらべる",meaning:"調查"},{word:"汚れる",reading:"よごれる",meaning:"弄髒、變髒"},{word:"犯人",reading:"はんにん",meaning:"犯人"}],questions:[{question:"冷蔵庫のドアには何が付いていましたか。",questionZh:"冰箱門上留有什麼？",options:["土で汚れた小さな手のあと","大きな手のあと","いちごのジュース","犬の毛"]},{question:"事件が起きたとき、おばあさんは何をしていましたか。",questionZh:"事件發生時，奶奶在做什麼？",options:["台所でお茶を飲んでいて、少し寝た","庭で犬と遊んでいた","部屋でゲームをしていた","外に買い物に行っていた"]},{question:"ケーキを食べたのはだれですか。",questionZh:"吃掉蛋糕的是誰？",options:["花","健","おばあさん","森さん"]}]},{id:"n4-r11",title:"雨の日の青い傘",titleZh:"雨天的藍色雨傘",topic:"推理",paragraphs:[{ja:"ある雨の日、山田先生の英語教室で、佐藤さんの新しい青い傘がなくなりました。教室の入り口の傘立てに置いておいたのに、授業が終わったときには、もうありませんでした。",zh:"某個下雨天，在山田老師的英語教室，佐藤同學的新藍色雨傘不見了。她明明把傘放在教室入口的傘架上，但下課時傘已經不在了。"},{ja:"その日、授業に来ていたのは、佐藤さんのほかに、木村さん、石井さん、林さんの三人でした。木村さんは授業の途中で「気分が悪いです」と言って、先に帰りました。石井さんと林さんは、最後まで教室にいました。",zh:"那天來上課的，除了佐藤同學以外，還有木村同學、石井同學和林同學三個人。木村同學在上課途中說「我不太舒服」，就先回家了。石井同學和林同學則一直待在教室到最後。"},{ja:"山田先生は窓の外を見て、「雨は授業の前から、ずっと強く降っていますね」と言いました。それから傘立てを見ました。そこには、古い黒い傘が一本だけ残っていました。石井さんと林さんは「私たちの傘はかばんの中です」と言って、ぬれた折りたたみ傘を見せました。佐藤さんも、その黒い傘は知らないと言いました。",zh:"山田老師看著窗外說：「雨從上課前就一直下得很大呢。」接著他看了看傘架。那裡只剩下一把舊的黑色雨傘。石井同學和林同學說「我們的傘在包包裡」，並拿出了濕掉的折疊傘。佐藤同學也說她不知道那把黑傘是誰的。"},{ja:"山田先生は「わかりました。佐藤さんの傘を持って行った人は、自分の傘とまちがえたのかもしれませんね」と言って、ある人に電話をかけ始めました。",zh:"山田老師說：「我知道了。拿走佐藤同學雨傘的人，可能是跟自己的傘搞錯了吧。」然後開始打電話給某個人。"}],vocab:[{word:"傘",reading:"かさ",meaning:"雨傘"},{word:"入り口",reading:"いりぐち",meaning:"入口"},{word:"授業",reading:"じゅぎょう",meaning:"上課、課程"},{word:"気分",reading:"きぶん",meaning:"身體狀況、心情"},{word:"降る",reading:"ふる",meaning:"（雨、雪）下"},{word:"残る",reading:"のこる",meaning:"剩下、留下"}],questions:[{question:"授業の途中で帰ったのはだれですか。",questionZh:"上課途中回家的是誰？",options:["木村さん","石井さん","林さん","佐藤さん"]},{question:"授業が終わったとき、傘立てには何がありましたか。",questionZh:"下課時，傘架上有什麼？",options:["古い黒い傘が一本","新しい青い傘が一本","ぬれた折りたたみ傘が二本","何もなかった"]},{question:"佐藤さんの傘を持って行ったのはだれだと考えられますか。",questionZh:"可以推測拿走佐藤同學雨傘的是誰？",options:["木村さん","石井さん","林さん","山田先生"]}]},{id:"n4-r12",title:"割れた窓ガラス",titleZh:"破掉的窗戶玻璃",topic:"推理",paragraphs:[{ja:"土曜日の朝、小林さんの家の窓ガラスが割れていました。部屋の中には、野球のボールが一つ落ちていました。前の日の夜はひどい雨でしたが、夜中の十二時ごろにやんだそうです。小林さんは、近くに住む探偵の青木さんに相談しました。",zh:"星期六早上，小林先生家的窗戶玻璃破了。房間裡掉了一顆棒球。前一天晚上下了很大的雨，但聽說在半夜十二點左右停了。小林先生找了住在附近的偵探青木先生商量。"},{ja:"青木さんは、近所の子ども三人に話を聞きました。ゆうたは「金曜日の夜、この前の道でキャッチボールをしていたけど、雨が降ってきたので、すぐ帰りました」と言いました。まさきは「土曜日の朝は、家族と車で山へ出かけていました」と言いました。けんじは「土曜日の朝は、ずっと家で寝ていました」と言いました。",zh:"青木先生向附近的三個孩子問話。優太說：「星期五晚上我在這前面的路上玩傳接球，但因為下雨了，所以馬上就回家了。」正樹說：「星期六早上我和家人開車去山上了。」健二說：「星期六早上我一直在家裡睡覺。」"},{ja:"青木さんはボールを手に取りました。ボールは少しもぬれていませんでした。それから窓の下を見ると、雨でやわらかくなった土の上に、くつのあとが残っていました。最後に、青木さんは三人のくつを見せてもらいました。けんじのくつにだけ、まだ新しい土が付いていました。",zh:"青木先生拿起了球。球一點也沒有濕。接著他看了窗戶下方，被雨淋得鬆軟的泥土上留著鞋印。最後，青木先生請三個人讓他看看鞋子。只有健二的鞋子上還沾著新的泥土。"},{ja:"青木さんは「窓が割れたのは、雨がやんだあとですね。犯人はもうわかりました」と言いました。",zh:"青木先生說：「窗戶是在雨停了以後才破的呢。我已經知道犯人是誰了。」"}],vocab:[{word:"窓",reading:"まど",meaning:"窗戶"},{word:"割れる",reading:"われる",meaning:"破裂、碎掉"},{word:"落ちる",reading:"おちる",meaning:"掉落"},{word:"相談",reading:"そうだん",meaning:"商量、諮詢"},{word:"寝る",reading:"ねる",meaning:"睡覺"},{word:"土",reading:"つち",meaning:"泥土"},{word:"残る",reading:"のこる",meaning:"剩下、留下"}],questions:[{question:"金曜日の夜の天気はどうでしたか。",questionZh:"星期五晚上的天氣怎麼樣？",options:["ひどい雨が降っていた","雪が降っていた","一晩中よく晴れていた","風は強かったが、雨は降らなかった"]},{question:"ボールがぬれていなかったことから、何がわかりますか。",questionZh:"從球沒有濕這件事，可以知道什麼？",options:["窓が割れたのは雨がやんだあとだ","窓が割れたのは金曜日の夜だ","ボールは家の中で使われていた","ボールは新しく買ったものだ"]},{question:"窓ガラスを割ったのはだれですか。",questionZh:"打破窗戶玻璃的是誰？",options:["けんじ","ゆうた","まさき","小林さん"]}]},{id:"n4-r13",title:"初めてのアルバイト",titleZh:"第一次打工",topic:"生活",paragraphs:[{ja:"高校二年生の私は、先月から駅の前のパン屋でアルバイトをしています。週に三回、学校が終わってから、夕方五時から八時まで働いています。",zh:"高中二年級的我，從上個月開始在車站前的麵包店打工。每週三次，放學後從傍晚五點工作到八點。"},{ja:"最初は、パンの名前と値段を覚えるのが大変でした。お客さんが多い時間に、レジでおつりをまちがえてしまったこともあります。でも、店長が「ゆっくりでいいから、ていねいにね」と言ってくれたので、少し安心しました。",zh:"一開始，要記住麵包的名字和價格很辛苦。在客人多的時段，我也曾經在收銀台找錯零錢。不過，店長對我說「慢慢來沒關係，要仔細喔」，讓我安心了一點。"},{ja:"今では、お客さんに「いつもありがとう」と言われることも増えました。また、店が閉まる前に残ったパンを安く売るので、ときどき家族のために買って帰ります。",zh:"現在，客人對我說「每次都謝謝你」的情況也變多了。另外，店裡在打烊前會便宜賣剩下的麵包，所以我有時會買回家給家人。"},{ja:"アルバイトを始めてから、お金をかせぐのは簡単ではないとわかりました。来週もらう初めての給料で、両親に小さなプレゼントを買うつもりです。",zh:"開始打工之後，我才明白賺錢並不容易。我打算用下星期要領的第一份薪水，買個小禮物送給爸媽。"}],vocab:[{word:"値段",reading:"ねだん",meaning:"價格"},{word:"店長",reading:"てんちょう",meaning:"店長"},{word:"安心",reading:"あんしん",meaning:"安心、放心"},{word:"閉まる",reading:"しまる",meaning:"關門、關閉"},{word:"簡単",reading:"かんたん",meaning:"簡單、容易"},{word:"給料",reading:"きゅうりょう",meaning:"薪水"},{word:"両親",reading:"りょうしん",meaning:"父母、雙親"}],questions:[{question:"この人は週に何回アルバイトをしていますか。",questionZh:"這個人每週打工幾次？",options:["三回","二回","五回","毎日"]},{question:"アルバイトを始めたころ、この人はどんな失敗をしましたか。",questionZh:"剛開始打工的時候，這個人犯了什麼錯？",options:["レジでおつりをまちがえた","パンを床に落としてしまった","アルバイトに遅れて行った","店のかぎをなくしてしまった"]},{question:"この人は、初めての給料で何をするつもりですか。",questionZh:"這個人打算用第一份薪水做什麼？",options:["両親に小さなプレゼントを買う","自分の新しい服を買う","全部銀行に入れておく","友だちと旅行に行く"]}]},{id:"n4-r14",title:"七夕の願いごと",titleZh:"七夕的願望",topic:"文化",paragraphs:[{ja:"七月七日は「七夕」です。昔の話では、おりひめとひこぼしという二人が、天の川の東と西に分かれて住んでいます。二人は一年に一度、この日の夜しか会うことができないと言われています。",zh:"七月七日是「七夕」。在古老的傳說裡，織女和牛郎兩個人分別住在銀河的東邊和西邊。據說兩人一年只有一次，只有在這天晚上才能見面。"},{ja:"七夕には、細長い紙に願いごとを書いて、竹の枝に付けます。この紙を「たんざく」と言います。子どもたちは「サッカーが上手になりますように」「おばあちゃんの病気が早く治りますように」など、いろいろな願いを書きます。",zh:"七夕時，人們會在細長的紙條上寫下願望，掛在竹子的枝條上。這種紙條叫做「短冊」。孩子們會寫下「希望足球能踢得更好」「希望奶奶的病能早點好」等各式各樣的願望。"},{ja:"町によっては、七夕祭りが開かれます。特に有名なのは仙台の七夕祭りで、毎年八月に、商店街に大きくてきれいな飾りがたくさん並びます。日本中から多くの人が見に来ます。",zh:"有些城鎮會舉辦七夕祭。其中特別有名的是仙台七夕祭，每年八月，商店街上都會排滿又大又漂亮的裝飾。很多人從日本各地前來觀賞。"},{ja:"ただ、七月の初めは雨の多い季節なので、雨や雲で星が見えない年も少なくありません。それでも人々は、空の上の二人が会えるようにと願いながら、夜空を見上げます。",zh:"不過，七月初是多雨的季節，所以因為下雨或雲層而看不到星星的年份也不少。即使如此，人們還是一邊祈禱天上的兩人能夠相會，一邊抬頭仰望夜空。"}],vocab:[{word:"願い",reading:"ねがい",meaning:"願望"},{word:"竹",reading:"たけ",meaning:"竹子"},{word:"枝",reading:"えだ",meaning:"樹枝、枝條"},{word:"治る",reading:"なおる",meaning:"（病）痊癒、治好"},{word:"祭り",reading:"まつり",meaning:"祭典、廟會"},{word:"飾り",reading:"かざり",meaning:"裝飾品"},{word:"星",reading:"ほし",meaning:"星星"}],questions:[{question:"七夕には、願いごとを書いた紙をどうしますか。",questionZh:"七夕時，寫了願望的紙條要怎麼處理？",options:["竹の枝に付ける","川に流す","家の玄関にはる","夜空に向かって飛ばす"]},{question:"文章の内容と合っているものはどれですか。",questionZh:"下列哪一項符合文章內容？",options:["雨や雲で星が見えない年も少なくない","おりひめとひこぼしは毎月一度会える","仙台の七夕祭りは七月七日に開かれる","願いごとは大人しか書いてはいけない"]}]},{id:"n4-r15",title:"旅行のおみやげ",titleZh:"旅行的伴手禮",topic:"文化",paragraphs:[{ja:"日本人は旅行に行くと、家族や友だちだけでなく、会社の人にもおみやげを買って帰ることが多いです。私は日本の会社で働き始めたとき、この習慣に驚きました。",zh:"日本人去旅行時，常常不只買伴手禮給家人和朋友，也會買給公司的同事。我剛開始在日本的公司上班時，對這個習慣感到很驚訝。"},{ja:"会社へのおみやげには、お菓子がよく選ばれます。特に、一つずつ袋に入っていて、数が多いお菓子が人気です。みんなに同じように配ることができるからです。",zh:"帶去公司的伴手禮常常會選點心。特別是一個一個單獨包裝、而且數量多的點心很受歡迎。因為可以平均分給每個人。"},{ja:"休みを取って旅行に行ったあと、「休みの間、ありがとうございました」という気持ちを伝えるために、おみやげを配るのだそうです。また、その町でしか買えないお菓子を食べながら、旅行の話をするのも楽しみの一つです。",zh:"據說，請假去旅行之後，是為了傳達「休假期間謝謝大家」的心意，才會分送伴手禮。另外，一邊吃只有那個地方才買得到的點心，一邊聊旅行的事，也是樂趣之一。"},{ja:"先月、私は京都へ旅行に行きました。帰ってきてから会社でお菓子を配ると、「京都はどうでしたか」と聞かれて、ほかの人と話すことが増えました。小さなお菓子ですが、人と人をつなぐ大切なものだと思います。",zh:"上個月，我去京都旅行。回來後在公司分送點心，同事問我「京都怎麼樣？」，我和其他人聊天的機會也變多了。雖然只是小小的點心，但我覺得它是連結人與人的重要東西。"}],vocab:[{word:"驚く",reading:"おどろく",meaning:"驚訝、吃驚"},{word:"お菓子",reading:"おかし",meaning:"點心、零食"},{word:"選ぶ",reading:"えらぶ",meaning:"選擇"},{word:"人気",reading:"にんき",meaning:"受歡迎"},{word:"配る",reading:"くばる",meaning:"分發、分送"},{word:"気持ち",reading:"きもち",meaning:"心情、心意"},{word:"伝える",reading:"つたえる",meaning:"傳達、轉告"}],questions:[{question:"会社へのおみやげには、どんなお菓子が人気ですか。",questionZh:"帶去公司的伴手禮，哪種點心很受歡迎？",options:["一つずつ袋に入っていて、数が多いお菓子","大きくて、一つしか入っていないお菓子","自分の家で作った手作りのお菓子","冷蔵庫に入れなければならないお菓子"]},{question:"日本人が会社の人におみやげを配るのはどうしてですか。",questionZh:"日本人為什麼要分送伴手禮給公司的同事？",options:["休みの間のお礼の気持ちを伝えるため","会社のルールで決まっているから","旅行の写真をみんなに見せるため","余ったお菓子を捨てたくないから"]},{question:"京都から帰ったあと、「私」の会社ではどんなことがありましたか。",questionZh:"從京都回來後，「我」在公司發生了什麼事？",options:["ほかの人と話すことが増えた","おみやげが足りなくて困った","みんなから京都のお菓子をもらった","次の旅行にさそわれた"]}]},{id:"n4-r16",title:"地震のときのために",titleZh:"為了地震發生的時候",topic:"社會",paragraphs:[{ja:"日本は地震が多い国です。大きな地震が起きると、電気や水道が止まって、何日も使えなくなることがあります。それで、多くの家では、ふだんから準備をしています。",zh:"日本是地震很多的國家。發生大地震時，電和自來水有時會停掉，好幾天都無法使用。所以，很多家庭平常就在做準備。"},{ja:"たとえば、水や、温めなくても食べられる食べ物を、家族みんなが三日ぐらい生活できる分だけ用意しておきます。それから、懐中電灯や電池、ラジオなどを一つのかばんに入れて、すぐに持って出られる場所に置いておきます。",zh:"例如，事先準備好足夠全家人生活大約三天的水和不用加熱也能吃的食物。另外，把手電筒、電池、收音機等放進一個包包裡，放在可以馬上帶著出門的地方。"},{ja:"また、家族で「地震のときはどこに逃げるか」「電話がつながらないときはどうするか」を話し合っておくことも大切です。学校や会社でも、年に何回か、逃げる練習をしています。",zh:"此外，家人事先討論好「地震時要逃到哪裡」「電話打不通時要怎麼辦」也很重要。學校和公司每年也會進行幾次逃生練習。"},{ja:"地震がいつ来るかは、だれにもわかりません。でも、準備をしておけば、あわてないで行動できます。今週末、家族といっしょにかばんの中を確かめてみようと思います。",zh:"地震什麼時候會來，誰都不知道。但是只要事先做好準備，就能不慌不忙地行動。這個週末，我打算和家人一起檢查看看包包裡的東西。"}],vocab:[{word:"地震",reading:"じしん",meaning:"地震"},{word:"準備",reading:"じゅんび",meaning:"準備"},{word:"用意",reading:"ようい",meaning:"準備、預備"},{word:"懐中電灯",reading:"かいちゅうでんとう",meaning:"手電筒"},{word:"電池",reading:"でんち",meaning:"電池"},{word:"逃げる",reading:"にげる",meaning:"逃跑、逃離"},{word:"確かめる",reading:"たしかめる",meaning:"確認、查看"}],questions:[{question:"文章によると、水や食べ物はどのぐらい用意しておくといいですか。",questionZh:"根據文章，水和食物最好事先準備多少？",options:["家族みんなが三日ぐらい生活できる分","家族みんなが一週間生活できる分","一人が一日だけ生活できる分","家族みんなが一か月生活できる分"]},{question:"家族で話し合っておくといいことは何ですか。",questionZh:"家人之間最好事先討論什麼事？",options:["地震のときにどこに逃げるか","どの店で電池を安く買えるか","次の休みにどこへ旅行するか","だれが毎日ラジオを聞くか"]}]},{id:"n4-r17",title:"日本の梅雨",titleZh:"日本的梅雨",topic:"自然",paragraphs:[{ja:"日本では、六月から七月の中ごろまで、雨の日が続きます。この季節を「梅雨」と言います。ちょうど梅の実が大きくなるころなので、この名前が付いたと言われています。",zh:"在日本，從六月到七月中旬左右，下雨的日子會一直持續。這個季節叫做「梅雨」。據說是因為正好是梅子果實長大的時候，所以取了這個名字。"},{ja:"梅雨の間は、空気がじめじめしていて、洗濯物がなかなか乾きません。また、食べ物が悪くなりやすいので、気をつけなければなりません。",zh:"梅雨期間，空氣濕答答的，洗好的衣服遲遲乾不了。另外，食物容易壞掉，所以必須小心。"},{ja:"でも、梅雨の雨は悪いことばかりではありません。田んぼの米や山の木が育つためには、たくさんの水が必要です。梅雨にしっかり雨が降らないと、夏に水が足りなくなることもあります。",zh:"但是，梅雨的雨並不全是壞事。稻田裡的稻米和山上的樹木要生長，需要大量的水。如果梅雨季沒有好好下雨，夏天有時會缺水。"},{ja:"梅雨のころには、あじさいの花がきれいに咲きます。雨にぬれたあじさいを見に、お寺や公園へ出かける人も多いです。雨の日にしか見られない景色を楽しむのも、いいかもしれません。",zh:"梅雨時節，繡球花會開得很漂亮。很多人會到寺廟或公園去看被雨淋濕的繡球花。享受只有雨天才看得到的景色，或許也不錯。"}],vocab:[{word:"梅雨",reading:"つゆ",meaning:"梅雨"},{word:"季節",reading:"きせつ",meaning:"季節"},{word:"続く",reading:"つづく",meaning:"持續、繼續"},{word:"乾く",reading:"かわく",meaning:"乾、變乾"},{word:"育つ",reading:"そだつ",meaning:"生長、成長"},{word:"足りる",reading:"たりる",meaning:"足夠"},{word:"景色",reading:"けしき",meaning:"景色、風景"}],questions:[{question:"「梅雨」という名前は、どうして付いたと言われていますか。",questionZh:"據說「梅雨」這個名字是怎麼來的？",options:["梅の実が大きくなるころだから","梅の花がきれいに咲くころだから","雨が梅のようなにおいがするから","この季節に梅を食べる習慣があるから"]},{question:"梅雨にしっかり雨が降らないと、どうなることがありますか。",questionZh:"如果梅雨季沒有好好下雨，可能會發生什麼事？",options:["夏に水が足りなくなる","夏がとても涼しくなる","秋に雨が降らなくなる","山の木が大きくなりすぎる"]}]},{id:"n4-r18",title:"虹はどうしてできるのか",titleZh:"彩虹是怎麼形成的",topic:"科學",paragraphs:[{ja:"雨がやんだあと、空に虹が出ることがあります。七つの色がきれいに並んでいて、見るとなんだかうれしい気持ちになります。虹は、どうしてできるのでしょうか。",zh:"雨停之後，天空有時會出現彩虹。七種顏色漂亮地排列著，看到的話總覺得心情很好。彩虹到底是怎麼形成的呢？"},{ja:"虹を作っているのは、太陽の光と、空気の中に残っている小さな水のつぶです。太陽の光は白く見えますが、実はいろいろな色がまざっています。光は水のつぶに入るとき、少し曲がります。その曲がり方は色によって少しずつ違うので、色が分かれて見えるのです。",zh:"形成彩虹的，是太陽光和殘留在空氣中的小水滴。太陽光看起來是白色的，但其實混合了各種顏色。光進入水滴時會稍微彎曲。彎曲的程度依顏色而有些微不同，所以顏色看起來就分開了。"},{ja:"虹は、太陽と反対の方向に出ます。ですから、朝は西の空に、夕方は東の空に見えることが多いです。昼ごろは太陽が高いので、虹はあまり見えません。",zh:"彩虹會出現在和太陽相反的方向。因此，早上常出現在西邊的天空，傍晚則常出現在東邊的天空。中午前後因為太陽很高，所以不太看得到彩虹。"},{ja:"虹は、家でも作ることができます。晴れた日に、太陽を背中にして、ホースで細かい水をまいてみてください。小さな虹が見えるはずです。",zh:"彩虹在家裡也能做出來。請在晴天時背對太陽，用水管灑出細細的水看看。應該就能看到小小的彩虹。"}],vocab:[{word:"虹",reading:"にじ",meaning:"彩虹"},{word:"並ぶ",reading:"ならぶ",meaning:"排列、並排"},{word:"曲がる",reading:"まがる",meaning:"彎曲、轉彎"},{word:"違う",reading:"ちがう",meaning:"不同"},{word:"分かれる",reading:"わかれる",meaning:"分開"},{word:"方向",reading:"ほうこう",meaning:"方向"},{word:"背中",reading:"せなか",meaning:"背、背部"}],questions:[{question:"虹は、どちらの方向に出ますか。",questionZh:"彩虹會出現在哪個方向？",options:["太陽と反対の方向","太陽と同じ方向","いつも北の方向","いつも南の方向"]},{question:"夕方、虹はどこに見えることが多いですか。",questionZh:"傍晚時，彩虹常出現在哪裡？",options:["東の空","西の空","南の空","太陽のすぐ近く"]},{question:"家で虹を作るときは、どうすればいいですか。",questionZh:"在家裡做彩虹時，應該怎麼做？",options:["太陽を背中にして、細かい水をまく","太陽のほうを向いて、細かい水をまく","雨の日に、部屋の電気を消してみる","夜に、庭でホースの水をまいてみる"]}]},{id:"n4-r19",title:"テーブルの上の花",titleZh:"桌上的花",topic:"推理",paragraphs:[{ja:"今日は母の誕生日です。午後四時に、私は母といっしょに買い物に出かけました。そのとき、台所のテーブルの上には何もありませんでした。でも、六時に帰ってくると、テーブルの上にきれいな花が置いてありました。カードには「いつもありがとう」とだけ書いてありました。",zh:"今天是媽媽的生日。下午四點，我和媽媽一起出門買東西。那時候，廚房的桌上什麼都沒有。但是六點回到家時，桌上放著一束漂亮的花。卡片上只寫著「謝謝妳一直以來的付出」。"},{ja:"花は、駅前の花屋の紙で包んでありました。その店は五時半に閉まります。父は朝から仕事で大阪へ行っていて、帰りは夜九時です。兄はサッカーの練習があるので、六時半まで学校にいます。",zh:"花是用車站前花店的包裝紙包著的。那家店五點半打烊。爸爸從早上就因為工作去了大阪，晚上九點才會回來。哥哥有足球練習，所以會待在學校到六點半。"},{ja:"私は姉の部屋へ行って、「何時に帰ってきたの」と聞きました。姉は「五時ごろ、電車で帰ってきたよ。それからずっと部屋で本を読んでいたの」と言って、にっこり笑いました。",zh:"我走到姊姊的房間，問她：「妳幾點回來的？」姊姊說：「五點左右搭電車回來的喔。之後就一直在房間看書。」然後笑咪咪的。"},{ja:"これでわかりました。私と母が出かけている間に家に帰ってきたのは、姉だけです。それに、姉は花屋が閉まる前に、駅の前を通って帰ってきました。花を置いたのは姉です。でも、姉はひみつにしたいようなので、私は母に言わないことにしました。",zh:"這樣我就知道了。我和媽媽出門的這段時間裡，回到家的只有姊姊。而且，姊姊是在花店打烊前經過車站前面回來的。放花的人就是姊姊。不過，姊姊好像想保密，所以我決定不告訴媽媽。"}],vocab:[{word:"誕生日",reading:"たんじょうび",meaning:"生日"},{word:"花屋",reading:"はなや",meaning:"花店"},{word:"包む",reading:"つつむ",meaning:"包、包裝"},{word:"閉まる",reading:"しまる",meaning:"關門、關閉"},{word:"練習",reading:"れんしゅう",meaning:"練習"},{word:"通る",reading:"とおる",meaning:"通過、經過"},{word:"笑う",reading:"わらう",meaning:"笑"}],questions:[{question:"「私」と母が出かけたとき、テーブルの上はどうでしたか。",questionZh:"「我」和媽媽出門時，桌上是什麼樣子？",options:["何もなかった","花が置いてあった","カードだけが置いてあった","ケーキが置いてあった"]},{question:"駅前の花屋は何時に閉まりますか。",questionZh:"車站前的花店幾點打烊？",options:["五時半","五時","六時","六時半"]},{question:"テーブルの上に花を置いたのはだれですか。",questionZh:"把花放在桌上的是誰？",options:["姉","兄","父","「私」"]}]},{id:"n4-r20",title:"料理クラブのクッキー",titleZh:"料理社的餅乾",topic:"推理",paragraphs:[{ja:"水曜日の放課後、料理クラブの部屋からクッキーがなくなりました。部長の中村さんが昼休みに一人で焼いたチョコレートのクッキーで、明日のパーティーでみんなを驚かせるつもりでした。中村さんが三時に部屋を出て、四時に戻ると、皿の上には一枚も残っていませんでした。",zh:"星期三放學後，料理社社辦裡的餅乾不見了。那是社長中村同學在午休時間獨自烤的巧克力餅乾，她本來打算在明天的派對上給大家一個驚喜。中村同學三點離開社辦，四點回來時，盤子上已經一片也不剩了。"},{ja:"その間に部屋の近くにいたのは、クラブの一年生三人だけでした。中村さんは三人に「クッキーがなくなったんだけど、何か知らない？」とだけ聞きました。",zh:"那段時間待在社辦附近的，只有社團的三個一年級生。中村同學只問了她們三人：「餅乾不見了，妳們知道些什麼嗎？」"},{ja:"山口さんは「ずっと音楽室で、先生とピアノを練習していました」と言いました。小川さんは「三時半に部屋に来たら、もうありませんでした」と言いました。松本さんは「昨日から一度も部屋に入っていません。チョコレートのクッキー、私も食べたかったな」と言いました。",zh:"山口同學說：「我一直在音樂教室和老師練鋼琴。」小川同學說：「我三點半來社辦的時候，餅乾已經不見了。」松本同學說：「我從昨天起就一次都沒進過社辦。巧克力餅乾啊，我也好想吃喔。」"},{ja:"中村さんは「クッキーの種類は、だれにも話していません。部屋に入っていない人が知っているはずはありませんね」と言いました。松本さんは顔を赤くして、「ごめんなさい。私が食べました」とあやまりました。",zh:"中村同學說：「餅乾的種類，我沒有跟任何人說過。沒進過社辦的人，不可能會知道吧。」松本同學紅著臉道歉說：「對不起，是我吃掉的。」"}],vocab:[{word:"放課後",reading:"ほうかご",meaning:"放學後"},{word:"部長",reading:"ぶちょう",meaning:"社長（社團負責人）"},{word:"焼く",reading:"やく",meaning:"烤、燒"},{word:"驚かせる",reading:"おどろかせる",meaning:"使驚訝、給驚喜"},{word:"戻る",reading:"もどる",meaning:"回來、返回"},{word:"皿",reading:"さら",meaning:"盤子"},{word:"種類",reading:"しゅるい",meaning:"種類"}],questions:[{question:"中村さんが部屋を出ていたのは、何時から何時までですか。",questionZh:"中村同學離開社辦的時間是幾點到幾點？",options:["三時から四時まで","昼休みの間","三時半から四時半まで","四時から五時まで"]},{question:"中村さんは、どうして松本さんが食べたとわかりましたか。",questionZh:"中村同學為什麼知道是松本同學吃的？",options:["松本さんがクッキーの種類を知っていたから","松本さんの口にチョコレートが付いていたから","松本さんが三時半に部屋に来たと言ったから","松本さんがピアノの練習に行かなかったから"]},{question:"クッキーを食べたのはだれですか。",questionZh:"吃掉餅乾的是誰？",options:["松本さん","山口さん","小川さん","中村さん"]}]}]},1922,[]);
